(window.GIM_TS=window.GIM_TS||{})["Rosh Hashanah.0"]={"from":0,"a":[["\u0003ארבעה ראשי שנים הם\u0004 כלומר, ארבעה ימים בשנה, משמשים, כל אחד, כראש השנה לענין מסויים; \u0003באחד בניסן\u0004 — \u0003ראש השנה למלכים,\u0004 שמתאריך זה מונים שנות שלטונו של המלך, וכן \u0003ל\u0004ענין ה\u0003רגלים\u0004 איזה מהם מוקדם ואיזה מאוחר.","\u0003באחד באלול\u0004 — \u0003ראש השנה למעשר בהמה,\u0004 שכל וולדות הבהמה הנולדים לפני אחד באלול, שייכים לשנת מעשר אחת ונמנים ומתעשרים כאחד, והנולדים לאחר מכן, שייכים לשנת מעשר שניה ואינם מתעשרים עם של קודמתה. \u0003ר' אלעזר ור' שמעון אומרים:\u0004 מעשר בהמה, ראש השנה שלו הוא \u0003באחד בתשרי.\u0004","\u0003באחד בתשרי\u0004 — \u0003ראש השנה ל\u0004מנין ה\u0003שנים, ול\u0004חשבון שנות \u0003השמיטין ול\u0004חשבון שנות ה\u0003יובלות,\u0004 שמשנכנס תשרי חל איסור מן התורה על כל עבודה בשדה. ו\u0003ל\u0004חשבון שנותיה של \u0003נטיעה\u0004 לענין איסור ערלה, \u0003ול\u0004ענין מעשר \u0003ירקות,\u0004 שאין מעשרים מירק של שנה אחת על ירק של שנה אחרת.","\u0003באחד בשבט\u0004 — \u0003ראש השנה ל\u0004ענין מעשר פירות ה\u0003אילן,\u0004 שאין מעשרים מפירות שחנטו בשנה אחת על אלו שחנטו בשנה אחרת, ופרי שכבר חנט וניכרת צורתו לפני תאריך זה, הריהו נחשב לענין מעשר כשל השנה שעברה, זהו \u0003כדברי בית שמאי\u0004 ואילו \u0003בית הלל אומרים:\u0004 ראש השנה לענין זה אינו אלא \u0003בחמשה עשר בו\u0004 (בשבט).","ושואלים: ראש השנה \u0003למלכים\u0004 שנזכר במשנה, \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 נקבע? מה צורך לקבוע תאריך מיוחד שעל פיו ימנו את שנות המלכים, ומדוע לא ימנו אותן לפי תאריך עלייתם לשלטון? \u0003אמר רב חסדא:\u0004 דבר זה נקבע משום ערכו \u0003ל\u0004גבי \u0003שטרות.\u0004 שהיו כותבים את התאריך בשטרות לפי מנין שנות המלוכה של המלך. ומשום כך חשוב ששנים אלה תתחלנה בתאריך קבוע כדי שיהיה ברור מהו שטר מוקדם ומהו שטר מאוחר.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת שביעית (פ\"י מ\"ה): \u0003שטרי חוב המוקדמין\u0004 שנכתב בהם תאריך המוקדם לזמן ביצוע ההלואה בפועל — הרי אלו \u0003פסולין,\u0004 שכן בכל מלוה בשטר משתעבדים נכסי הלווה למלוה משעת ההלואה, ואם לא נפרע החוב יכול המלוה לטרוף את נכסי הלווה שנמכרו לאחר מכן מאת הקונה ולהפרע חובו מהם, ואם התאריך המצויין בשטר מוקדם לזמן ההלואה בפועל, יתכן שטורף נכסים שאינם מגיעים לו על פי הדין. \u0003ו\u0004שטרי חוב \u0003המאוחרין\u0004 שהתאריך המצויין בהם לאחר זמן ההלואה בפועל — \u0003כשרין,\u0004 שאילו היה התאריך המצויין בשטר כפוף לזמן עלייתו של המלך בפועל לשלטון, היתה נוצרת אפשרות לטעות אם יום זה היה למשל בשנה ראשונה או שניה של מלכותו. אולם כאשר הכל מונים את שנות המלוכה מתאריך קבוע (אחד בניסן), הכל יודעים שעברה שנה ואין טועים בכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מלך שעמד\u0004 (עלה לשלטון) \u0003בעשרים ותשעה באדר, כיון שהגיע אחד בניסן\u0004 אף על פי שלא מלך בפועל אלא יום אחד בלבד — \u0003עלתה לו שנה,\u0004 כלומר, נסתיימה השנה הראשונה למלכותו, ומאחד בניסן מונים לו שנה שניה. \u0003ואם לא עמד אלא באחד בניסן\u0004 — \u0003אין מונין לו שנה\u0004 למלכותו \u0003עד שיגיע ניסן אחר.\u0004 ומעתה באים לפרש את דברי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מלך שעמד בעשרים ותשעה באדר, כיון שהגיע אחד בניסן\u0004 — \u0003עלתה לו שנה ראשונה למלכותו.\u0004 ומעירים: \u0003הא\u0004"],["\u0003קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 בברייתא זו: כי \u0003ניסן\u0004 הוא \u0003ראש השנה למלכים. ו\u0004עוד למדנו בכך, כי \u0003יום אחד בשנה חשוב שנה,\u0004 שאף שלא מלך אלא יום אחד בשנה שעברה, הרי הוא נחשב כשנת שלטון שלימה. ושואלים: מה שנאמר בהמשך \u0003\"ואם לא עמד אלא באחד בניסן\u0004 — \u0003אין מונין לו שנה עד שיגיע ניסן אחר\",\u0004 לכאורה דין זה הוא \u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן מאליו\u0005]!\u0006","ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא באופן \u0003דאימנו עליה\u0004 \u0005[שנמנו עליו]\u0006 והסכימו להמליכו עוד \u0003מ\u0004חודש \u0003אדר, מהו דתימא\u0004 \u0005[שתאמר]\u0006 שמאחר וההחלטה על המלכתו היתה כבר בחודש אדר, ייחשב הדבר כאילו כבר המליכוהו בפועל באדר, ואם כן \u0003נימנו ליה תרתין שנין\u0004 \u0005[שימנו לו,\u0006 למלכותו \u0005שתי שנים],\u0006 לכך \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מחשבים את שנות המלכות אלא משעה שמלך בפועל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מת\u0004 המלך \u0003ב\u0004חודש \u0003אדר ועמד\u0004 מלך \u0003אחר תחתיו באדר\u0004 — \u0003מונין שנה לזה,\u0004 למלך הקודם, שהיא שנתו האחרונה, \u0003ולזה,\u0004 למלך החדש, שמאדר מתחילה שנת מלכותו הראשונה. \u0003מת\u0004 המלך \u0003בניסן ועמד\u0004 מלך \u0003אחר תחתיו בניסן\u0004 — \u0003מונין שנה לזה ולזה. מת\u0004 המלך \u0003באדר ועמד\u0004 מלך \u0003אחר תחתיו בניסן\u0004 — \u0003מונין\u0004 את השנה ה\u0003ראשונה ל\u0004מלך ה\u0003ראשון\u0004 כשנת מלכותו האחרונה, \u0003ו\u0004את ה\u0003שניה לשני,\u0004 כשנת מלכותו הראשונה.","ומפרשים: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מת באדר ועמד אחר תחתיו באדר\u0004 — \u0003מונין שנה לזה ולזה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומסבירים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003שתא לבי תרי לא מנינן\u0004 \u0005[שנה\u0006 אחת, כשנת שלטון, \u0005לשני\u0006 מלכים \u0005אין אנו מונים],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לכך.","נאמר בתוספתא: \u0003\"מת בניסן ועמד אחר תחתיו בניסן\u0004 — \u0003מונין שנה לזה ולזה\",\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 כי \u0003יום אחד בשנה חשוב\u0004 כ\u0003שנה\u0004 שלימה — הרי זה דווקא כשיום זה הוא \u0003בסוף שנה,\u0004 שכיון שאחר כך מתחילה שנת מנין חדשה, מונים לו אותו כשנה שלימה. \u0003אבל\u0004 אם יום זה הוא \u0003בתחלת שנה\u0004 — \u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 כן, ולא נמנה את ראשית חודש ניסן כשנה נוספת למלך הקודם, שהרי לא סיים שנה שלימה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מחלקים בכך.","עוד נאמר בתוספתא: \u0003מת באדר ועמד אחר תחתיו בניסן\u0004 — \u0003מונין ראשונה לראשון ושניה לשני.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא באופן \u0003דאימנו עליה\u0004 \u0005[שנמנו עליו]\u0006 להמליכו עוד \u0003מ\u0004חודש \u0003אדר, ו\u0004בנוסף לכך \u0003מלך בן מלך הוא,\u0004 שירושת השלטון ודאית במקרה כזה, ועל כן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003נימנו ליה תרתין שנין\u0004 \u0005[שימנו לו שתי שנים]\u0006 בניסן, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מונים לו אלא מניסן שהוא זמן עלותו לשלטון בפועל.","אמר \u0003ר' יוחנן: מנין למלכים שאין מונין להם\u0004 את שנותיהם \u0003אלא מניסן\u0004 — \u0003שנאמר: \"ויהי בשמונים שנה וארבע מאות שנה לצאת בני ישראל מארץ מצרים בשנה הרביעית בחדש זו הוא החדש השני למלך שלמה על ישראל\u0004 ויבן הבית לה'\u0003\"\u0004 (מלכים א' ו, א) — \u0003מקיש\u0004 (משוה) בפסוק זה את \u0003מלכות שלמה ליציאת מצרים; מה יציאת מצרים\u0004 מונים אותה, כמפורש בכתוב, \u0003מניסן\u0004 — \u0003אף מלכות שלמה\u0004 מונים אותה \u0003מניסן.\u0004","ושואלים: \u0003ו\u0004את השנים ל\u0003יציאת מצרים גופה\u0004 \u0005[עצמה]\u0006 \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 ש\u0003מניסן מנינן\u0004 \u0005[מונים אנו]?\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003מתשרי מנינן\u0004 \u0005[מונים אנו]\u0006 אותם?","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 שכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויעל אהרן הכהן אל הר ההר על פי ה' וימת שם בשנת הארבעים לצאת בני ישראל מארץ מצרים בחדש החמישי באחד לחדש\"\u0004 (במדבר לג, לח), \u0003וכתיב\u0004 \u0005[ונאמר\u0006 עוד\u0005]:\u0006 \u0003\"ויהי בארבעים שנה בעשתי עשר חדש באחד לחדש דבר משה\u0004 אל בני ישראל\" (דברים א, ג); \u0003מדקאי\u0004 \u0005[מכיון שעומד]\u0006 \u0003ב\u0004חודש \u0003אב\u0004 שהוא החודש החמישי, \u0003וקרי\u0004 \u0005[וקורא]\u0006 \u0003לה\u0004 לשנה זו \u0003\"שנת ארבעים\" וקאי\u0004 \u0005[ועומד]\u0006 \u0003בשבט שלאחריו, שהוא\u0004 חודש אחד עשר \u0003וקרי\u0004 \u0005[וקורא]\u0006 \u0003לה,\u0004 אף לאותה שנה \u0003\"שנת ארבעים\"\u0004 — \u0003מכלל\u0004 הדברים תלמד ש\u0003ראש השנה לאו\u0004 \u0005[לא]\u0006 \u0003חודש תשרי הוא,\u0004 שכן אם היה ראש השנה בתשרי — הרי לא יתכן שגם חודש אב, החודש החמישי וגם חודש שבט שלאחריו (שהוא החודש האחד עשר) יהיו שניהם בשנה אחת.","ומקשים: \u0003בשלמא היאך\u0004 \u0005[נניח\u0006 תאריך \u0005זה]\u0006 של מיתת אהרן \u0005— הלא\u0006 \u0003מפרש\u0004 \u0005[מפורש\u0006 בכתוב\u0005]\u0006 שהוא בשנת הארבעים \u0003ליציאת מצרים\u0004 (\"בשנת הארבעים לצאת בני ישראל מארץ מצרים\"), \u0003אלא האי\u0004 \u0005[זה],\u0006 התאריך של ארבעים שנה אשר בו דיבר משה, \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 אתה יודע ש\u0003ליציאת מצרים\u0004 הוא מונה, \u0003דילמא\u0004 \u0005[שמא]\u0006 מונה הוא ארבעים שנה \u0003להקמת המשכן?\u0004","ומשיבים: \u0003כ\u0004פי ש\u0003אמר רב פפא\u0004 לענין אחר, שכשנאמר במקרא בשני מקומות \u0003\"שנת עשרים\", \"שנת עשרים\",\u0004 נלמד הדבר \u0003לגזרה שוה,\u0004 לומר שמדובר בשנת עשרים לאותו מנין, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 זה שנאמר בשני המקומות \u0003\"שנת ארבעים\" \"שנת ארבעים\"\u0004 יש ללומדו \u0003לגזרה שוה\u0004 ולהבין שמדובר בשנת הארבעים לאותו מנין, ו\u0003מה כאן\u0004 במיתת אהרן מפורש שהוא \u0003ליציאת מצרים, אף כאן\u0004 בדיבור משה, אף שלא נתפרש לאיזה אירוע, הרי זה ודאי \u0003ליציאת מצרים.\u0004","ועוד שואלים: גם אם הוכחנו ששני המאורעות הללו היו בשנה אחת, \u0003וממאי\u0004 \u0005[וממה]\u0006 יודע אתה ש\u0003מעשה\u0004 זה של מיתת אהרן שהיה בחודש \u0003אב קדים\u0004 \u0005[\u0006הוא \u0005המוקדם],\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 ה\u0003מעשה\u0004 של חודש \u0003שבט,\u0004 דברי משה, \u0003קדים\u0004 \u0005[קדמו],\u0006 ובאופן זה יתכן שהשנה מתחילה אכן מתשרי ושני המאורעות היו אכן באותה שנה!","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 שכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 בדברי משה, שהיו אלו \"אחר \u0003י הכתו את סיחון\"\u0004 (דברים א, ד), \u0003וכי נח נפשיה\u0004 \u0005[ו\u0006הלא מאוחר יותר, \u0005כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003אהרן אכתי הוה\u0004 \u0005[עדיין היה]\u0006 \u0003סיחון קיים, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006"],["\u0003\"וישמע הכנעני מלך ערד\u0004 יושב הנגב כי בא ישראל וילחם בישראל וישב ממנו שבי\" (במדבר לג, מ), \u0003מה שמועה שמע?\u0004 — \u0003שמע שמת אהרן, ו\u0004ש\u0003נסתלקו ענני כבוד\u0004 מישראל, \u0003וכסבור\u0004 כי \u0003ניתנה\u0004 לו \u0003רשות\u0004 (אפשרות) \u0003להלחם בישראל\u0004 ולנצחם. \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"ויראו כל העדה כי גוע אהרן\u0004 ויבכו את אהרן שלושים יום כל בית ישראל\u0003\"\u0004 (במדבר כ, כט),","\u0003ואמר ר' אבהו: אל תקרי \"ויראו\"\u0004 מלשון ראיה, \u0003אלא \"וייראו\"\u0004 שנראו הם לאחרים, כיון שהוסר מהם כיסוי ענני הכבוד \u0003וכ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש:\u0004 המונח \u0003\"כי\" משמש\u0004 בכתוב \u0003בארבע לשונות\u0004 (מובנים): לשון \u0003אי\u0004 \u0005[אם],\u0006 לשון \u0003דילמא\u0004 \u0005[שמא],\u0006 לשון \u0003אלא,\u0004 ולשון \u0003דהא\u0004 \u0005[שכן,\u0006 שהרי\u0005],\u0006 ואף כאן שנאמר \"ויראו כל העדה כי גווע אהרן\", יש להבין \"כי\" זה שהוא במובן \"דהא\" (שהרי). וכך פירושו: כל העדה נראו, נתגלו, מפני שגווע אהרן. הרי שבזמן מיתת אהרן עדיין היה סיחון קיים, ועל כרחך יש לומר שדברי משה שנאמרו \"אחרי הכותו את סיחון\" נאמרו מאוחר יותר.","אולם על גוף ההוכחה מקשים: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם\u0004 \u0005[שם]\u0006 מדובר במלחמה כנגד מלך ערד שהוא \u0003כנען,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בפסוק זה מדובר ב\u0003סיחון\u0004 ומה ראיה אם כן מזה לזה? ומסבירים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 כל השמות הללו של אדם אחד הם; \u0003הוא סיחון, הוא ערד, הוא כנען.\u0004 וכך משמעם: \u0003\"סיחון\"\u0004 — \u0003שדומה\u0004 בפראותו \u0003לסייח במדבר, \"כנען\"\u0004 — \u0003על שם מלכותו\u0004 שהוא מולך על העם הכנעני, \u0003ומה שמו\u0004 האמיתי — \u0003\"ערד\" שמו. איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 באופן אחר: \u0003\"ערד\"\u0004 נקרא מפני \u0003שדומה לערוד\u0004 (חמור בר) \u0003במדבר, \"כנען\"\u0004 — \u0003על שם מלכותו, ומה שמו\u0004 — \u0003\"סיחון\" שמו.\u0004 ושואלים עוד לענין התאריכים: אכן, הוכחנו שבמנין השנים, החודש החמישי (אב), קודם לחודש האחד עשר (שבט) ושניהם שייכים לשנה אחת, אולם עדיין לא הוכחנו שראש השנה הוא בניסן דווקא.","\u0003ואימא\u0004 \u0005[ואמור]\u0006 כי \u0003ראש השנה\u0004 הוא בחודש \u0003אייר!\u0004","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 שכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויהי בחדש הראשון בשנה השנית באחד לחדש הוקם המשכן\"\u0004 (שמות מ, יז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 עוד: \u0003\"ויהי בשנה השנית בחדש השני\u0004 בעשרים בחדש \u0003נעלה הענן מעל משכן העדת\"\u0004 (במדבר י, יא). וכך יש להוכיח: \u0003מדקאי\u0004 \u0005[מכיון שהוא עומד]\u0006 \u0003ב\u0004חודש \u0003ניסן וקרי\u0004 \u0005[וקורא]\u0006 \u0003לה\u0004 לאותה שנה \"\u0003שנה שנית\", וקאי\u0004 \u0005[ועומד]\u0006 \u0003ב\u0004חודש \u0003אייר\u0004 (\"בחודש השני\") \u0003וקרי\u0004 \u0005[וקורא]\u0006 אף \u0003לה \"שנה שנית\"\u0004 — \u0003מכלל\u0004 הדברים אתה למד כי \u0003ראש השנה לאו\u0004 \u0005[לא]\u0006 חודש \u0003אייר הוא!\u0004","ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 אולי ש\u0003ראש השנה\u0004 בחודש \u0003סיון הוא!\u0004 ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 שכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"בחדש השלישי לצאת בני ישראל מארץ מצרים\u0004 ביום הזה באו מדבר סיני\u0003\"\u0004 (שמות יט, א), \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לומר שראש השנה הוא בחודש סיון אם כן \u0003\"בחדש השלישי בשנה השנית לצאת\u0004 בני ישראל מארץ מצרים \u0003\"מיבעי ליה\u0004 \u0005[היה לו]\u0006 לומר, שהרי זו שנה חדשה!","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 בחודש \u0003תמוז הוא! ואימא\u0004 \u0005[ואמור]\u0006 שראש השנה בחודש \u0003אב הוא! ואימא\u0004 \u0005[ואמור]\u0006 שראש השנה בחודש \u0003אדר הוא!\u0004 כלומר, עדיין אין לנו ראיה ברורה לגבי כל שאר החודשים!","\u0003אלא אמר ר' אלעזר: מהכא\u0004 \u0005[מכאן]\u0006 למדים אנו, שנאמר: \u0003\"ויחל לבנות בחדש השני בשני בשנת ארבע למלכותו\"\u0004 (דברי הימים ב' ג, ב) ומדייקים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"\u0004ב\u0003שני\"\u0004 שנאמר בכתוב זה? \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003שני לירח\u0004 \u0005[לחודש]\u0006 \u0003שמונין בו למלכותו,\u0004 ומכאן הוכחה ברורה שמונים למלכות מהחודש הראשון, שהוא חודש ניסן.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: ואימא\u0004 \u0005[ואמור]\u0006 כי \"בשני\" זה, הכוונה ל\u0003שני\u0004 ל\u0003חדש!\u0004 ענה לו: \u0003אם כן \"שני בחדש\" בהדיא הוה כתיב ביה\u0004 \u0005[במפורש היה\u0006 צריך להיות \u0005נאמר בו]\u0006 שכאשר מצויין בכתוב היום המדוייק בחודש, נאמר במפורש שהוא יום פלוני בחודש.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003ש\"בשני\"\u0004 כוונתו ליום השני \u0003בשבת\u0004 (בימי השבוע)! ודוחים: אין אתה יכול לומר כן; \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד],\u0006 \u0003דלא אשכחן\u0004 \u0005[שלא מצאנו]\u0006 \u0003שני בשבת דכתיב\u0004 \u0005[שנאמר]\u0006 שלא מצאנו בלשון המקרא ציון ימות השבוע. \u0003ועוד\u0004 יש לדחות: \u0003מקיש\u0004 (משווה) \u0003\"שני\" בתרא\u0004 \u0005[אחרון]\u0006 \u0003ל\"שני\" קמא\u0004 \u0005[ראשון],\u0006 \u0003מה \"שני\" קמא\u0004 \u0005[ראשון]\u0006 מפורש בו שהוא \u0003חדש, אף שני בתרא\u0004 \u0005[אחרון]\u0006 הכוונה ל\u0003חדש.\u0004","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: מנין שאין מונין להם למלכים\u0004 את שנות המלוכה \u0003אלא מ\u0004חודש \u0003ניסן\u0004 — \u0003שנאמר: \"ויהי בשמונים שנה וארבע מאות שנה לצאת בני ישראל מארץ מצרים\u0004 בשנה הרביעית בחודש זיו למלוך שלמה על ישראל ויבן הבית לה' \"\u0003(מלכים א' ו, א), וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויעל אהרן הכהן אל הר ההר על פי ה'\u0004 וימת שם בשנת הארבעים לצאת בני ישראל מארץ מצרים בחודש החמישי באחד לחודש\" (במדבר לג, לח), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי בארבעים שנה בעשתי עשר חדש\u0004 באחד לחודש דבר משה אל בני ישראל ככל אשר צוה ה' אותו עליהם\u0003\"\u0004 (דברים א, ג),","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"אחרי הכתו את סיחון\u0004 מלך האמורי אשר יושב בחשבון\u0003\"\u0004 (דברים א, ד) \u0003ואומר: \"וישמע הכנעני\u0004 מלך ערד והוא יושב בנגב בארץ כנען בבוא בני ישראל\u0003\"\u0004 (במדבר לג, מ), \u0003ואומר: \"ויראו כל העדה כי גוע אהרן\u0004 ויבכו את אהרן שלושים יום\u0003\"\u0004 (במדבר כ, כט) \u0003ואומר: \"ויהי בחדש הראשון בשנה השנית\u0004 באחד לחודש הוקם המשכן\u0003\"\u0004 (שמות מ, יז),","\u0003ואומר: \"ויהי בשנה השנית בחדש השני\u0004 בעשרים לחודש נעלה הענן מעל משכן העדות\u0003\"\u0004 (במדבר י, יא), \u0003ואומר: \"בחדש השלישי לצאת בני ישראל\u0004 מארץ מצרים ביום הזה באו מדבר סיני\u0003\"\u0004 (שמות יט, א), \u0003ואומר: \"ויחל לבנות\u0004 בחודש השני בשני בשנת ארבע למלכותו\u0003\"\u0004 (דברי הימים ב' ג, ב), שהוא סיכום קצר של ההוכחות שהביא רבי יוחנן.","\u0003אמר רב חסדא: לא שנו\u0004 שמונים למלכים את שנות המלוכה מאחד בניסן \u0003אלא למלכי ישראל בלבד, אבל למלכי אומות העולם\u0004 — \u0003מתשרי מנינן\u0004 \u0005[מונים אנו]\u0006 את שנות מלכותם, \u0003שנאמר: \"דברי נחמיה בן חכליה ויהי בחדש כסלו שנת עשרים\u0004 ואני הייתי בשושן הבירה\u0003\"\u0004 (נחמיה א, א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי בחדש ניסן שנת עשרים לארתחשסתא\u0004 ואשא את היין ואתנה למלך ולא הייתי רע לפניו\u0003\"\u0004 (נחמיה ב, א).","וכך יש להוכיח: \u0003מדקאי\u0004 \u0005[מכיון שהוא עומד]\u0006 \u0003ב\u0004חודש \u0003כסליו וקרי ליה\u0004 \u0005[וקורא לה],\u0006 לשנה זו, \u0003\"שנת עשרים\" וקאי\u0004 \u0005[ועומד הוא]\u0006 \u0003ב\u0004חודש \u0003ניסן וקרי ליה\u0004 \u0005[וקורא לה],\u0006 לשנה זו, \u0003\"שנת עשרים\"\u0004 — \u0003מכלל\u0004 הדברים אתה למד כי \u0003ראש השנה\u0004 במנין זה \u0003לאו\u0004 \u0005[לא]\u0006 חודש \u0003ניסן הוא.\u0004","ושואלים: \u0003בשלמא היאך\u0004 \u0005[נניח זה]\u0006 המנין האמור בפסוק השני — \u0003מפרש\u0004 שהוא \u0003לארתחשסתא, אלא האי\u0004 \u0005[זה]\u0006 המנין בפסוק הראשון \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 יודע אתה \u0005שהוא\u0006 \u0003לארתחשסתא? דילמא\u0004 \u0005[שמא]\u0006"],["\u0003למנינא אחרינא\u0004 \u0005[למנין אחר]\u0006 \u0003הוא\u0004 מונה? \u0003אמר רב פפא: \"שנת עשרים\" \"שנת עשרים\"\u0004 שנאמר בשני הכתובים \u0003לגזירה שוה\u0004 הוא בא, \u0003מה התם\u0004 \u0005[שם]\u0006 מפרש שהיא שנת עשרים \u0003לארתחשסתא, אף הכא\u0004 \u0005[כאן]\u0006 הכוונה \u0003לארתחשסתא.\u0004","ושואלים: \u0003וממאי\u0004 \u0005[וממה,\u0006 מנין\u0005]\u0006 יודע אתה שה\u0003מעשה\u0004 של \u0003כסליו קדים [\u0004הוא ש\u0005קדם],\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 ה\u0003מעשה\u0004 של \u0003ניסן קדים\u0004 \u0005[\u0006הוא ש\u0005קדם],\u0006 ואכן מונים אף למלכי אומות העולם מניסן?","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אותם \u0003דברים שאמר חנני לנחמיה ב\u0004חודש \u0003כסליו, אמרן נחמיה למלך ב\u0004חודש \u0003ניסן.\u0004","ומפרטים: \u0003דברים שאמר חנני לנחמיה בכסליו\u0004 — \u0003שנאמר: \"דברי נחמיה בן חכליה ויהי בחדש כסלו שנת עשרים ואני הייתי בשושן הבירה. ויבא חנני אחד מאחי הוא ואנשים מיהודה ואשאלם על היהודים הפליטה אשר נשארו מן השבי ועל ירושלים. ויאמרו לי הנשארים אשר נשארו מן השבי שם במדינה ברעה גדולה ובחרפה וחומת ירושלים מפרצת ושעריה נצתו באש\"\u0004 (נחמיה א-ג).","ודברים אלו הם ש\u0003אמרן נחמיה למלך בניסן, שנאמר: \"ויהי בחדש ניסן שנת עשרים לארתחשסתא המלך יין לפניו ואשא את היין ואתנה למלך ולא הייתי רע לפניו. ויאמר לי המלך מדוע פניך רעים ואתה אינך חולה אין זה כי אם רע לב ואירא הרבה מאד. ואמר למלך המלך לעולם יחיה מדוע לא ירעו פני אשר העיר בית קברות אבתי חרבה ושעריה אכלו באש.\u0004","\u0003ויאמר לי המלך על מה זה אתה מבקש ואתפלל אל אלהי השמים. ואמר למלך אם על המלך טוב ואם ייטב עבדך לפניך אשר תשלחני אל יהודה אל עיר קברות אבתי ואבננה. ויאמר לי המלך והשגל יושבת אצלו עד מתי יהיה מהלכך ומתי תשוב וייטב לפני המלך וישלחני ואתנה לו זמן\"\u0004 (נחמיה ב א-ו).","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 על כלל זה שקבע רב חסדא, והלא נאמר: \u0003\"ביום עשרים וארבעה לחדש בששי בשנת שתים לדריוש\u0004 המלך\u0003\"\u0004 (חגי א, טו) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 מיד בסמוך לו: \u0003\"בשביעי בשנת שתים בעשרים ואחד לחדש\u0004 היה דבר ה' ביד חגי הנביא לאמור\u0003\"\u0004 (חגי ב, א), \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום להנחה זו שמונים למלכי האומות מחודש תשרי הלא \u0003\"בשביעי בשנת שלש\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006","\u0003אמר ר' אבהו:\u0004 יש לומר, כי \u0003כורש מלך כשר היה,\u0004 ו\u0003לפיכך מנו לו\u0004 את חשבון שנות מלכותו \u0003כ\u0004שנות \u0003מלכי ישראל,\u0004 מחודש ניסן.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף\u0004 על תירוץ זה: \u0003חדא\u0004 \u0005[אחת]\u0006 יש להקשות — ש\u0003אם כן קשו קראי אהדדי\u0004 \u0005[קשים הכתובים זה על זה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושיציא ביתה דנה עד יום תלתה לירח אדר די היא שנת שת למלכות דריוש מלכא\"\u0004 \u0005[ונגמר בית זה עד יום שלושה לחודש אדר שהוא שנת שש למלכות דרויש המלך]\u0006 (עזרא ו, טו), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003באותו זמן לשנה הבאה עלה עזרא מבבל וגלותו,\u0004 בני הגולה שהעלה, \u0003עמו. וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003במקרא: \"ויבא ירושלים בחדש החמישי היא שנת השביעית למלך\"\u0004 (עזרא ז, ח) \u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לסברה שחדשי מלכותו נמנו כשל מלכי ישראל מחודש ניסן — הלא \u0003\"שנת השמינית\" מיבעי ליה\u0004 \u0005[היה צריך לו\u0006 לומר\u0005]!\u0006","\u0003ועוד\u0004 יש להקשות על דברי רבי אבהו: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר בפסוקים? והלא \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003כורש,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר ב\u0003דריוש,\u0004 ועל דריוש הלא לא אמרו שהיה מלך כשר! ומשיבים: זה אינו קשה, כי \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הוא כורש, הוא דריוש, הוא ארתחשסתא,\u0004 וכולם שמות וכינויים של מלך אחד. ומפרטים: \u0003כורש\u0004 הוא נקרא, מתוך \u0003שמלך כשר היה\u0004 (כורש בחילוף אותיות — כשר), ונקרא \u0003ארתחשסתא, על שם מלכותו\u0004 — שהוא תוארו המלכותי, \u0003ומה שמו\u0004 האמיתי — \u0003דריוש שמו.\u0004","ומקשים: \u0003מכל מקום קשיא\u0004 \u0005[\u0006הרי \u0005קשה],\u0006 שממקום אחד נראה שנמנו שנות מלכותו מחודש ניסן ובמקום אחר רואים שמניינן מחודש תשרי! \u0003אמר ר' יצחק, לא קשיא\u0004 \u0005[אין זה קשה],\u0006 ויש לפרש: \u0003כאן\u0004 שמנו לו מחודש ניסן כמלכי ישראל, מדובר \u0003קודם שהחמיץ\u0004 (שהתקלקל), \u0003כאן\u0004 שמנו לו כמלכי גוים, מדובר \u0003לאחר שהחמיץ.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב כהנא: ומי\u0004 \u0005[והאם]\u0006 \u0003החמיץ\u0004 וקלקל מעשיו כאשר עלה עזרא? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006"],["\u0003\"ומה חשחן ובני תורין ודכרין ואמרין לעלון לאלה שמיא חנטין מלח חמר ומשח כמאמר כהניא די בירושלם להוא מתיהב להם יום ביום די לא שלו\"\u0004 \u0005[ומה שהם צריכים, ובני בקר ואילים וטלאים לעלות לאלהי השמים, חיטים, מלח, יין ושמן, כמאמר הכהנים אשר בירושלים שינתן להם יום ביום בלי לשכוח]\u0006 (עזרא ו, ט). הרי שגילה יראת שמים שנדב נדבה זו למקדש! \u0003אמר לו ר' יצחק לרב כהנא: רבי, מטונך\u0004 \u0005[ממשאך],\u0006 מכתוב זה עצמו שהבאת יש תשובה לדבריך, שהרי מסיים שם: \u0003\"די להון מהקרבין ניחוחין לאלה שמיא ומצלין לחיי מלכא ובנוהי\"\u0004 \u0005[כדי שיהיו מקריבים עולות לאלהי השמים ומתפללים לחיי המלך ובניו]\u0006 (עזרא ו, י), הרי שהתכוון בכך אף לשם עצמו.","ותוהים: \u0003ומאן דעבד הכי\u0004 \u0005[ומי שעושה כך]\u0006 \u0003לאו מעליותא\u0004 \u0005[\u0006האם \u0005לא מעלה]\u0006 \u0003היא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ה\u0004נותן סלע לצדקה ו\u0003אומר: \"סלע זו לצדקה בשביל שיחיו בני\",\u0004 או שאומר שנותנה \u0003\"בשביל שאזכה בה לחיי העולם הבא\"\u0004 — \u0003הרי זה צדיק גמור.\u0004 ואם כן, מה הפגם בכך שנדב המלך קרבנות לחייו ולחיי בניו?","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003כאן בישראל,\u0004 אף שנותן בתנאי הרי זה צדיק גמור, כיון שהדבר ברור שאף אם בסופו של דבר לא יתקבל תנאו, לא יקרא תגר חס ושלום כלפי שמים. \u0003כאן\u0004 שנחשב הדבר שקלקול, מדובר \u0003בגוים,\u0004 והגוי אינו נחשב כצדיק אם מתכוון בנתינתו לשם מטרה כלשהי, שכן אם אין בקשתו מתמלאת הרי הוא מתחרט וקורא תגר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מנלן דאחמיץ\u0004 \u0005[מניין לנו שהחמיץ,\u0006 שהתקלקל\u0005]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בבנין המקדש, שצוה לעשות \u0003\"נדבכין די אבן גלל תלתא ונדבך די אע חדת ונפקתא מן בית מלכא תתיהב\"\u0004 \u0005[נדבכים של אבן שלושה, ונדבך של עץ חדש, וההוצאה מבית המלך תנתן]\u0006 (עזרא ו, ד), ויש להבין \u0003למה ליה\u0004 \u0005[לו]\u0006 \u0003דעבד הכי\u0004 \u0005[שעשה כך]\u0006 עצים ואבנים יחד? אלא ודאי \u0003סבר\u0004 \u0005[חשב]:\u0006 \u0003אי מרדו בי יהודאי\u0004 \u0005[אם ימרדו בי היהודים]\u0006 — \u0003איקלייה בנורא\u0004 \u0005[אשרוף אותו,\u0006 את בנין בית המקדש \u0005באש],\u0006 שאם יהיו העצים חלק מן הבנין ייקל למוטטו בשריפה.","ותוהים: \u0003אטו\u0004 \u0005[האם]\u0006 \u0003שלמה\u0004 המלך כשבנה את בית המקדש הראשון \u0003לא עבד הכי\u0004 \u0005[עשה כך]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"\u0004ויבן את החצר הפנימית \u0003שלשה טורי גזית וטור כרתת ארזים\"\u0004 (מלכים א' ו, לו)! ומשיבים: \u0003שלמה עבד\u0004 \u0005[עשה,\u0006 בנה\u0005]\u0006 את העצים \u0003מלמעלה\u0004 שאף בשריפתם עדיין ישאר מסד האבן, \u0003ואיהו עבד\u0004 \u0005[והוא,\u0006 דריוש \u0005עשה]\u0006 אותם \u0003מלמטה\u0004, שבשריפתם יתמוטט כל הבנין. ועוד: \u0003שלמה שקעיה בבנינא\u0004 \u0005[שיקע אותם,\u0006 את העצים, \u0005ב\u0006תוך \u0005הבנין],\u0006 ובכך מנע מגע אש אפשרית בעצים, ואילו \u0003איהו\u0004 \u0005[הוא\u0006 דריוש\u0005],\u0006 \u0003לא שקעיה בבנינא\u0004 \u0005[שיקע אותם ב\u0006תוך \u0005הבנין].\u0006 וכן: \u0003שלמה סדייה בסידא\u0004 \u0005[סייד אותם\u0006 את העצים \u0005בסיד],\u0006 דבר העשוי לעכב את הבעירה, ואילו \u0003איהו\u0004 \u0005[הוא],\u0006 דריוש \u0003לא סדייה בסידא\u0004 \u0005[סד אותם בסיד].\u0006","\u0003אמר רב יוסף, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק: מנלן\u0004 \u0005[מנין לנו]\u0006 \u0003דאחמיץ\u0004 \u0005[שהחמיץ]\u0006 דריוש — \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ויאמר לי המלך והשגל יושבת אצלו\u0004 עד מתי יהיה מהלכך ומתי תשוב ויטב לפני המלך וישלחני ואתנה לו זמן \u0003\"(נחמיה ב, ו). ומבארים: מאי\u0004 \u0005[מהו]\u0006 \u0003\"שגל\"\u0004 זה האמור בכתוב? \u0003אמר רבה בר לימא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כלבתא\u0004 \u0005[כלבה]\u0006 היתה זו שישבה לידו, שהיה מייחד אותה לו למשכב.","ומקשים: \u0003אלא מעתה, הא דכתיב\u0004 \u0005[זה שנאמר]:\u0006 \u0003בבלשאצר: \"ועל מרא שמיא התרוממת ולמאניא די ביתיה היתיו קדמך ואנת ורברבנך שגלתך ולחנתך חמרא שתין בהון\"\u0004 \u0005[ועל אדון השמים התנשאת ואת כלי ביתו הביאו לפניך ואתה וגדוליך ושגלותיך ופילגשיך יין שותים בהם]\u0006 (דניאל ה, כג), \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003\"שגל\"\u0004 זה האמור בכתוב \u0003כלבתא\u0004 \u0005[כלבה]\u0006 \u0003היא,\u0004 וכי \u0003כלבתא\u0004 \u0005[כלבה]\u0006 \u0003בת משתיא חמרא\u0004 \u0005[שתיית יין]\u0006 \u0003היא?\u0004 ומתרצים: \u0003הא לא קשיא\u0004 \u0005[\u0006דבר \u0005זה אינו קשה],\u0006 שיתכן להעמיד את הדבר במקרה מסויים; \u0003דמלפא לה ושתייא\u0004 \u0005[שמלמדים אותה והיא שותה].\u0006","ומקשים: \u0003אלא מעתה\u0004 מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בנות מלכים ביקרותיך נצבה שגל לימינך בכתם אופיר\"\u0004 (תהלים מה, י) \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003שגל כלבתא\u0004 \u0005[כלבה]\u0006 \u0003היא, מאי קא\u0004 \u0005[מה\u0006 אם כן\u0005]\u0006 \u0003מבשר להו\u0004 \u0005[להם]\u0006 ה\u0003נביא לישראל\u0004 שיהיו לימינם כלבות?! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 \u0003בשכר שחביבה תורה לישראל כ\u0004שם שחביבה \u0003שגל לגוים\u0004 — \u0003זכיתם לכתם אופיר.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 פירוש \u0003\"שגל\"\u0004 האמור בכל שאר הכתובים — \u0003מלכתא\u0004 \u0005[מלכה]\u0006 \u0003היא, ו\u0004אולם \u0003רבה בר לימא, גמרא גמיר לה\u0004 \u0005[\u0006ב\u0005מסורת היה למוד]\u0006 דבר זה, ש\"שגל\" האמורה בכתוב זה היתה כלבה, \u0003ואמאי קרי\u0004 \u0005[ומדוע קרא]\u0006 \u0003לה \"שגל\"\u0004 — \u0003שהיתה חביבה עליו\u0004 כלבה זו \u0003כשגל\u0004 (כמלכה). \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לומר בביאור הענין \u0003שהושיבה\u0004 לידו \u0003במקום שגל.\u0004","\u0003איבעית אימא\u0004 \u0005[\u0006ו\u0005אם תרצה אמור]:\u0006 \u0003מנלן דאחמיץ\u0004 \u0005[מניין לנו שהתקלקל]\u0006 — \u0003מהכא\u0004 \u0005[מכאן]\u0006 שנאמר: \u0003\"עד כסף ככרין מאה ועד חנטין כורין מאה ועד חמר בתין מאה ועד בתין משח מאה ומלח די לא כתב\" [עד כסף מאה ככרות ועד חיטים מאה כורים ויין מאה בת (\u0004סאה\u0005), מאה בת שמן, ומלח שלא נכתב]\u0006 (עזרא ז, כב), וממשמעות הפסוק למדים אנו כי \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 נתן \u0003בלא קיצותא\u0004 \u0005[קיצבה]\u0006 \u0003והשתא בקיצותא\u0004 \u0005[ועכשיו בקיצבה].\u0006","ודוחים: \u0003ודילמא מעיקרא\u0004 \u0005[ושמא מתחילה]\u0006 \u0003לא הוה קים ליה בקיצותא\u0004 \u0005[היה ברור לו בקיצבה]\u0006 שלא ידע מה צורך המקדש בכל יום, ואחר כך כשנודעו לו השיעורים המדוייקים, קבע בהתאם לכך כמות מסויימת. \u0003אלא, מחוורתא כדשניין מעיקרא\u0004 \u0005[מחוור,\u0006 ברור \u0005כפי שתירצנו,\u0006 הסברנו \u0005מתחילה].\u0006","שנינו במשנה כי ראש השנה לרגלים הוא באחד בניסן. ושואלים: ראש השנה ל\u0003רגלים, באחד בניסן הוא?\u0004 והלא \u0003בחמשה עשר בניסן הוא,\u0004 שהרי אז מתחיל הרגל, חג הפסח! \u0003אמר רב חסדא,\u0004 הכוונה היא: \u0003רגל שבו,\u0004 שבחודש זה, הוא \u0003ראש השנה לרגלים.\u0004","ולגוף הדבר, מה הוא עניינו של ראש השנה לרגלים — \u0003נפקא מינה\u0004 \u0005[יוצא מזה]\u0006 להלכה \u0003ל\u0004ענין \u0003נודר, למיקם עליה\u0004 \u0005[לעמוד\u0006 לעבור \u0005עליו]\u0006 \u0003ב\u0004עבירה של \u0003\"בל תאחר\" ו\u0004כשיטת \u0003ר' שמעון היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003: אחד הנודר\u0004 קרבן למקדש, \u0003ואחד המקדיש\u0004 דבר למקדש. \u0003ואחד המעריך\u0004 ערך לקודש, \u0003כיון שעברו עליו שלשה רגלים\u0004 מאותו יום ולא שילם את נדרו — \u0003עובר ב\"בל תאחר\".\u0004","\u0003ר' שמעון אומר:\u0004 לא שלושה רגלים סתם, אלא \u0003שלשה רגלים כסדרן וחג המצות תחילה,\u0004 שלעולם יש להתחיל לענין זה מחג הפסח. \u0003וכן היה ר' שמעון בן יוחי אומר: רגלים\u0004 שעדיין יכול לאחר מבלי שיעבור על \"בל תאחר\" ולהביא בהם את הקרבנות שנדר, \u0003פעמים שלשה\u0004 הם, \u0003פעמים ארבעה, פעמים חמשה. כיצד?\u0004 אם \u0003נדר\u0004 נדר \u0003לפני הפסח\u0004 — הרי \u0003שלשה\u0004 רגלים הם שיכול לאחר עד חג הסוכות. נדר \u0003לפני עצרת\u0004 — הרי הם חמישה רגלים, שאין מתחילים למנות לו אלא מפסח הבא. ואם נדר \u0003לפני החג\u0004 (סוכות) — ארבעה רגלים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חייבי הדמין,\u0004 כלומר, מי שנדר שדמיו (מחירו, ערכו) או דמי אחר יהיו הקדש, או \u0003ערכין,\u0004 או \u0003חרמין\u0004 (סוג של הקדש) שנדב למקדש, או \u0003ההקדשות,\u0004 וכן קרבנות \u0003חטאות,\u0004 או \u0003אשמות,\u0004 או \u0003עולות,\u0004 או \u0003שלמים,\u0004 וכן נדרים של \u0003צדקות,\u0004 או \u0003מעשרות\u0004 דגן, וכן קרבנות \u0003בכור,\u0004 או \u0003מעשר\u0004 בהמה, או קרבן \u0003פסח,\u0004"],["או \u0003לקט שכחה ופאה\u0004 שהופרשו ועדיין לא נטלום העניים, \u0003כיון שעברו עליהן שלשה רגלים\u0004 ולא נתן — הרי זה \u0003עובר ב\"בל תאחר\". ר' שמעון אומר: שלשה רגלים\u0004 אלו, צריכים שיהיו \u0003כסדרן, וחג המצות תחלה.\u0004","\u0003ר' מאיר אומר: כיון שעבר עליהן רגל אחד\u0004 בלבד — הרי זה \u0003עובר ב\"בל תאחר\", ר' אליעזר בן יעקב אומר: כיון שעברו עליהן שני רגלים\u0004 — \u0003עובר ב\"בל תאחר\". ר' אלעזר בר' שמעון אומר: כיון שעבר עליהן חג הסוכות\u0004 — \u0003עובר עליהן ב\"בל תאחר\".\u0004","ומבארים את השיטות: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה הטעם של התנא הראשון]\u0006 — \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003מיניהו סליק\u0004 \u0005[מהם,\u0006 מן הרגלים, \u0005הוא יוצא]\u0006 שהפרק כולו עוסק בענין שלושת הרגלים, ואם כן, \u0003למה לי למהדר ומיכתב\u0004 \u0005[לחזור ולכתוב]\u0006 בסיכומו: \u0003\"בחג המצות ובחג השבעות ובחג הסכות\u0004 ולא יראה את פני ה' ריקם \u0003\"(דברים טז, טז)? אלא ודאי שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי דבר זה נכתב \u0003ל\u0004ענין \u0003\"בל תאחר\".\u0004","\u0003ור' שמעון\u0004 האומר כי שלושה רגלים אלו צריכים להיות כסידרם, \u0003אומר\u0004 בביאור שיטתו: \u0003אינו צריך לומר\u0004 בפסוק זה \u0003\"בחג הסוכות\", ש\u0004הרי \u0003בו דיבר הכתוב\u0004 בפסוקים הקודמים לזה, אם כן \u0003למה\u0004 בכל זאת \u0003נאמר\u0004 — \u0003לומר שזה אחרון.\u0004 כלומר, שהסדר המנוי בכתוב זה הוא הסדר המחייב.","\u0003ור' מאיר\u0004 האומר כי די ברגל אחד כדי לעבור ב\"בל תאחר\", \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 שיטתו\u0005]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי אם אל המקום אשר יבחר ה' מכל שבטיכם לשום את שמו שם לשכנו תדרשו ובאת שמה. והבאתם שמה\u0004 עולותיכם וזבחיכם ואת מעשרותיכם ואת תרומת ידכם ונדריכם ונדבותיכם ובכורות בקרכם וצאנכם\" (דברים יב, ה-ו) ומי שלא הביא מיד ברגל הראשון כאשר חלה עליו החובה של \"ובאת שמה\" — הרי זה עובר.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים,\u0006 תנא קמא\u0005]\u0006 הסוברים כי אינו עובר ב\"בל תאחר\" אלא לאחר שעברו שלושה רגלים, כיצד מבינים הם כתוב זה? ומשיבים: לדעתם הכתוב \u0003ההוא\u0004 מלמד שמצות \u0003עשה\u0004 היא להביא את נדריו ברגל הראשון, ואולם אם לא הביא מיד, אף שעבר בעשה — אינו עובר במצות לא תעשה.","ושואלים: \u0003ור' מאיר\u0004 מה משיב הוא לטענה זו? לדעתו \u0003כיון דאמר ליה רחמנא אייתי\u0004 \u0005[שאמרה לו התורה הבא]\u0006 את הקרבן במועד זה \u0003ולא אייתי\u0004 \u0005[הביא]\u0006 — \u0003ממילא קם ליה\u0004 \u0005[עומד הוא]\u0006 \u0003ב\u0004איסור \u0003\"בל תאחר\", שהרי איחר מן המועד שקבעה התורה.\u0004","ושואלים: \u0003ור' אליעזר בן יעקב\u0004 האומר כי עובר ב\"בל תאחר\" לאחר שני רגלים, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 שיטתו\u0005]?\u0006 ומסבירים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלה תעשו לה' במועדיכם\u0004 לבד מנדריכם ונדבותיכם לעולותיכם ולמנחותיכם ולנסכיכם ולשלמיכם\" (במדבר כט, לט) וכיון שנקבעה הבאת הנדרים במועדים — \u0003מיעוט מועדים שנים.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 כיצד מפרשים הם פסוק זה — \u0003ההוא\u0004 מתפרש \u0003לכ\u0004 פי שאמר \u0003ר' יונה.\u0004 ש\u0003אמר ר' יונה: הוקשו\u0004 (הושוו) \u0003כל המועדים כולם זה לזה,\u0004 לומר, \u0003ש\u0004כל שעירי החטאת שמביאים, \u0003כולם מכפרים על טומאת מקדש וקדשיו\u0004 כפי שמכפר שעיר ראש חודש.","ושואלים: \u0003ור' אלעזר בר' שמעון\u0004 האומר כי שמשעבר חג הסוכות ולא הביא מיד הוא עובר ב\"בל תאחר\", \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 שיטתו\u0005]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' אלעזר בר' שמעון אומר: לא יאמר\u0004 בכתוב זה (דברים טז, טז) \u0003\"חג הסכת\",\u0004 שהרי \u0003בו דיבר הכתוב\u0004 קודם לכן, ואם כן \u0003למה\u0004 בכל זאת \u0003נאמר\u0004 — \u0003לומר ש\u0004חג \u0003זה\u0004 הוא ה\u0003גורם\u0004 שייחשב הנודר כמאחר להביא נדריו, שחייב להביא את כל נדריו עד סוף החג, בין שנדר סמוך לו בין הרבה לפניו.","ושואלים: \u0003ור' מאיר ור' אליעזר בן יעקב האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"בחג המצות ובחג השבעות ובחג הסכות\" מאי דרשו ביה\u0004 \u0005[מה דורשים הם בו]\u0006 ומה למדים הם ממנו? ומשיבים: \u0003מיבעי להו\u0004 \u0005[צריכים הם אותו]\u0006 \u0003ל\u0004כפי ש\u0003אמר ר' אלעזר אמר ר' אושעיא,\u0004 ש\u0003אמר ר' אלעזר אמר ר' אושעיא מניין לעצרת\u0004 (חג השבועות) \u0003שיש לה תשלומין כל שבעה\u0004 ימים אחרי יום טוב, שקרבנות שלא הביא בחג השבועות עצמו יכול להביאו עוד שישה ימים נוספים לאחר מכן? — \u0003תלמוד לומר: \"בחג המצות ובחג השבעות ובחג הסכות\", מקיש\u0004 (משווה) \u0003חג השבועות לחג המצות, מה חג המצות יש לו תשלומין כל שבעה,\u0004 שהרי לאחר יום החג הראשון יש עוד שישה ימים של חג — \u0003אף חג השבועות יש לו תשלומין כל שבעה.\u0004","ושואלים: \u0003אם כן, וליקש\u0004 \u0005[ושיקיש,\u0006 ישווה\u0005]\u0006 אותו \u0003לחג הסוכות\u0004 שאף הוא נזכר בסמוך לו, ויאמר: \u0003מה להלן\u0004 בסוכות, מספר ימי החג \u0003שמונה\u0004 ימים — \u0003אף כאן\u0004 בעצרת, יהיו תשלומיו \u0003שמונה\u0004 ימים! ודוחים: אי אפשר לומר כן, שאף בסוכות יש רק שבעה ימים. כי היום ה\u0003שמיני רגל בפני עצמו הוא.\u0004","ומקשים: \u0003אימור דאמרינן\u0004 \u0005[אמור שאנו אומרים]\u0006 כי היום ה\u0003שמיני רגל בפני עצמו\u0004 הוא דווקא \u0003לענין פז\"ר קש\"ב\u0004 (\u0003שישה דברים שיש בו: פ\u0004 ייס בין משמרות הכהנים מי מקריב קרבנותיו, שנעשה כחג בפני עצמו ולא כהמשך לפייסות של סוכות. וכן לענין ברכת \u0003ז\u0004 מן (\"שהחיינו\") שיש לאומרה בשמיני בפני עצמה. ושהוא נחשב \u0003ר\u0004 גל בפני עצמו לענין חובת עלייה לרגל. וכן, שהוא \u0003ק\u0004 רבן חג בפני עצמו, שאינו המשך סדר מוספי חג הסוכות. ושיש בו \u0003ש\u0004יר חג מיוחד בפני עצמו. וכן שיש בו \u0003ב\u0004רכה בפני עצמה (שמזכירים חג זה בתפילות ובברכות כחג בפני עצמו), \u0003אבל לעניין תשלומין\u0004 של חובות החג — \u0003דברי הכל\u0004 כל שיהיה מוקרב בו \u0003תשלומין\u0004 של \u0003ראשון הוא,\u0004 שאף הוא נחשב כהמשך ליום החג הראשון!","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שלא חג\u0004 (הביא קרבן חגיגה) ב\u0003יום טוב הראשון של חג\u0004 הסוכות — \u0003חוגג\u0004 (מקריב) \u0003את כל הרגל, ו\u0004אף ב\u0003יום טוב האחרון של חג.\u0004 משמע שאף יום השמיני בכלל החג הוא! ואם כן מדוע שלא נקיש את חג השבועות דווקא לחג הסוכות שבו שמונה ימים?","ומסבירים: עדיף להשוות את חג השבועות לפסח ולא לסוכות בשל הכלל: \u0003תפשת מרובה\u0004 — \u0003לא תפשת, תפשת מועט\u0004 — \u0003תפשת,\u0004 ולכן כפי שעושים אנו בכל מקום, יש ללמוד דווקא מן המספר הקטן ולא מן הגדול.","ושואלים: \u0003ואלא\u0004 אם כן \u0003למאי הלכתא כתביה רחמנא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה כתבה התורה]\u0006 בפסוק זה את \u0003חג הסוכות\u0004 שאין למדים ממנו לכאורה דבר? ומשיבים: \u0003לאקושיה\u0004 \u0005[להשוותו]\u0006 \u0003לחג המצות\u0004 לענין אחר."],["\u0003מה חג המצות טעון לינה\u0004 שחייב ללון בירושלים במוצאי החג, ואינו רשאי לשוב לביתו אלא למחרת החג — \u0003אף חג הסוכות טעון\u0004 כמו כן \u0003לינה\u0004 בירושלים טרם שוב העולים לרגל אל ביתם.","ושואלים: \u0003והתם\u0004 \u0005[ושם]\u0006 בחג המצות \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דין זה? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 בקרבן הפסח \"ובשלת ואכלת במקום אשר יבחר ה' בו \u0003ופנית בבקר והלכת לאהליך\"\u0004 (דברים טז, ז).","ושואלים: \u0003ותנא קמא, ור' שמעון\u0004 הלומדים מן הפסוק \"בחג המצות ובחג השבועות ובחג הסוכות\" (דברים טז, טז), כי אינו עובר ב\"בל תאחר\" אלא לאחר שעברו שלושה רגלים (כל אחד כשיטתו), אם כן דין \u0003תשלומין לעצרת מנא להו\u0004 \u0005[מניין להם]?\u0006","ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא להם]\u0006 הדבר \u0003מדתני\u0004 \u0005[ממה ששנה]\u0006 \u0003רבה בר שמואל. דתני\u0004 \u0005[ששנה]\u0006 \u0003רבה בר שמואל: אמרה תורה מנה ימים וקדש חדש\u0004 (כפי שנאמר: \"חודש ימים\". במדבר יא, כ), וכן \u0003מנה ימים וקדש עצרת\u0004 שהרי העצרת (שבועות) נקבעת על פי מספר הימים לאחר הפסח (שנאמר: \"תספרו חמישים יום\". ויקרא כג, טז). ונלמד מכאן: \u0003מה חדש למנויו,\u0004 כלומר, קרבן ראש החודש מובא באחד מן הימים שמונים בהם את החודש, \u0003אף עצרת למנויו,\u0004 שיש יום מיוחד להקרבת קרבנות החג.","ושואלים: \u0003אם כן אימא\u0004 \u0005[אמור]\u0006 שתהיה \u0003עצרת\u0004 רק \u0003חד יומא\u0004 \u0005[יום אחד]\u0006 ומהיכן למד אתה שיש שבוע שלם להקרבה? \u0003אמר רבא: אטו\u0004 \u0005[וכי]\u0006 ב\u0003עצרת יומי מנינן שבועי לא מנינן\u0004 \u0005[ימים אנו מונים,\u0006 אולם \u0005שבועות אין אנו מונים]?\u0006 \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003מצוה למימני יומי\u0004 \u0005[למנות ימים]\u0006 חמשים יום, \u0003ומצוה למימני שבועי\u0004 \u0005[למנות שבועות]\u0006 שבעה שבועות, וההיקש מלמדנו איפוא שיש שבוע שלם לקרבנות החג. \u0003ועוד:\u0004 הלא \u0003\"חג שבועות\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003משמע: חג שנקבע על ידי מנין שבועות.\u0004","בין הדברים שמנתה הברייתא כאלו שעוברים עליהם ב\"בל תאחר\" נמנה גם הפסח, ועל כן תוהים: \u0003ו\u0004כי ה\u0003פסח בר מיקרב\u0004 \u0005[ראוי להקרבה]\u0006 \u0003ברגלים הוא?\u0004 והלא \u0003פסח זימנא קביעא ליה\u0004 \u0005[זמן קבוע\u0006 יש \u0005לו],\u0006 בארבעה עשר בניסן, \u0003אי אקרביה\u0004 \u0005[אם הקריבו]\u0006 — \u0003אקרביה\u0004 \u0005[הקריבו],\u0006 \u0003ואי לא אקרביה\u0004 \u0005[ואם לא הקריבו]\u0006 — \u0003אידחי ליה\u0004 \u0005[נדחה לו]!\u0006","\u0003אמר רב חסדא: פסח כדי נסבה\u0004 \u0005[לריק הביאו],\u0006 שהפסח אכן אינו שייך לענין \"בל תאחר\" ובברייתא הוכנס רק משום שגרת הלשון המצויה \"בכור, מעשר ופסח\".","\u0003רב ששת אמר\u0004 הסבר אחר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"פסח\"\u0004 כאן — \u0003שלמי פסח.\u0004 שאם אבד הכבש שהופרש לקרבן הפסח, והפריש בעליו כבש אחר והקריבו כפסח, ואחרי כן נמצא הראשון, הרי הוא כשלמים לכל דיניו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 מה שכבר נאמר שם \u0003שלמים\u0004 ואין איפוא כל חידוש בדבר! ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003שלמים הבאין מחמת פסח, ותנא\u0004 \u0005[ושנה]\u0006 \u0003שלמים הבאין מחמת עצמן.\u0004 וטעם ההכפלה, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל\u0004 ושלמים אלה \u0003מחמת פסח קאתו\u0004 \u0005[הם באים],\u0006"],["ואם כן \u0003כפסח\u0004 עצמו \u0003דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 ואם לא הקריבם מיד יעבור עליהם ולא תינתן לו הזדמנות נוספת להקריבם — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהם בכלל כל הנדרים וזמן כולם שווה.","לגופה של ההלכה שואלים: \u0003מנהני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שעל כל הקרבנות והנדרים המנויים באותה ברייתא עובר משום \"בל תאחר\"? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר, \u0003\"כי תדר נדר\u0004 לה' אלוהיך לא תאחר לשלמו כי דרוש ידרשנו ה' אלהיך מעמך והיה בך חטא \u0003\"(דברים כג, כב), אין לי אלא נדר\u0004 שאדם מקבל התחייבות זו על עצמו בנדר (בלשון \"הרי עלי להביא...\"), אולם \u0003נדבה\u0004 שמפריש את הבהמה (בלשון \"הרי זו\"), בלא להתחייב באחריותה, \u0003מנין\u0004 שאף היא בכלל איסור זה של \"בל תאחר\"?","ומשיבים: \u0003נאמר כאן \"נדר\" ונאמר להלן \"\u0004ו\u0003אם נדר או נדבה\u0004 זבח קרבנו \u0003\"(ויקרא ז, טז). מה להלן\u0004 שנאמר נדר, \u0003נדבה עמו\u0004 ודינה כמותו, \u0003אף כאן\u0004 — \u0003נדבה עמו.\u0004","נאמר \"\u0003לה' אלקיך\" (דברים כג, כב) — אלו הדמין\u0004 כלומר מה שאדם נודב דמיו (ערכו) של דבר מה, ו\u0003הערכין והחרמין וההקדשות\u0004 שכולם באים לבדק בית ה'. נאמר שם \u0003\"לא תאחר לשלמו\"\u0004 (דברים כג, כב) ויש כאן הדגשה: לשלם אותו דווקא, כלומר: \u0003הוא ולא חילופיו,\u0004 לומר שעל חילופיו אינו עובר ב\"בל תאחר\". נאמר: \u0003\"כי דרש ידרשנו\"\u0004 (דברים כג, כב) הרי זו לשון המורה על כל דבר שנדרש ממך להביאו — \u0003אלו חטאות ואשמות עולות\u0004 (ראיה) \u0003ושלמים\u0004 (שלמי חגיגה), שכל אלו בכלל הדברים שחובה עליו להביאם.","\u0003\"ה' אלהיך\"\u0004 שנאמר שם בהמשך הוא לכאורה כתוב מיותר, שכן כבר נאמר בכגון זה לפני כן, ודי אם היה אומר \"כי דרוש ידרשנו\", ומיתור זה למדים לרבות דברים נוספים: \u0003אלו צדקות ומעשרות\u0004 דגן \u0003ובכור. \"מעמך\"\u0004 (דברים כג, כב) — ללמד שנותן משלו דברים אחרים לשם מצוה, \u0003זה לקט שכחה ופאה\u0004 הניתן לעניים. \u0003\"והיה בך חטא\"\u0004 (דברים כג, כב) — להדגיש: \u0003ולא בקרבנך חטא,\u0004 לומר שאין הקרבן נפסל בכך.","ומעתה מבררים כמה דברים בברייתא זו, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003\"לא תאחר לשלמו\"\u0004 — \u0003הוא ולא חילופיו,\u0004 לומר שדין זה חל על הקרבן עצמו ולא על בהמה שהביאו כחילופין לו. \u0003חילופי מאי\u0004 \u0005[מה],\u0006 בחילופי איזה קרבן מדובר כאן? \u0003אי\u0004 \u0005[אם]\u0006 תאמר כי מדובר ב\u0003חילופי עולה ושלמים\u0004 שנדר להקריבם ואבדו, והביא אחרים (חילופים) תחתיהם — הרי אין בכך חידוש, שהרי אלו בכל מקרה בהמות אלו שהפריש בשנית כעולה או שלמים \u0003מקרב קרבי\u0004 \u0005[קרבים הם]\u0006 כקרבנות הראשונים, ואינם שונים מהם בדינם.","\u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 תאמר שהמדובר ב\u0003חילופי חטאת,\u0004 שאבדה בהמת חטאת והפריש אחרת תחתיה, ונתכפר בה ולאחר מכן נמצאה הראשונה, הרי יודעים אנו שזו שנשארה \u0003למיתה אזלא\u0004 \u0005[הולכת],\u0006 שאין מקריבים אותה אלא גורמים לה שתמות, ואם כן אין כאן מקום לומר שיעבור עליה משום \"בל תאחר\". \u0003אלא\u0004 יש לומר \u0003מאי\u0004 \u0005[מהם]\u0006 \u0003חילופיו\u0004 — \u0003חילופי תודה.\u0004","\u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא\u0004 בברייתא: קרבן \u0003תודה שנתערבה בתמורתה,\u0004 שהמיר את קרבן תודה שהפריש כבר, בבהמה אחרת, ונתערבו התודה ותמורתה זו בזו, \u0003ומתה אחת מהן\u0004 — \u0003חברתה אין לה תקנה.\u0004 ומדוע?","\u0003היכי ליעביד\u0004 \u0005[כיצד יעשה]?\u0006 \u0003ליקרבה וליקריב\u0004 \u0005[שיקריבנה ויקריב]\u0006 את \u0003לחם\u0004 התודה \u0003בהדה\u0004 \u0005[איתה]\u0006 — יש לחשוש \u0003דלמא\u0004 \u0005[שמא]\u0006 בהמה זו אינה זו שהפריש בתחילה, אלא \u0003תמורה היא\u0004 ותמורת תודה אמנם קריבה כתודה עצמה, אולם שלא כמותה, הריהי קריבה בלא לחם. ואם תאמר כי \u0003ליקרבה\u0004 \u0005[שיקריבנה]\u0006 \u0003בלא לחם —\u0004 יש לחשוש \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003תודה היא\u0004 והקרבת הלחם היא חלק מתהליך הקרבת התודה עצמה. ומתוך שחילופי תודה אינם יכולים להיות קרבים — אינו עובר עליהם \"בבל תאחר\", וחליפיו שאמרנו בברייתא — חילופי תודה הם.","ומקשים: \u0003והא כיון דלאו בת הקרבה היא\u0004 \u0005[וזו, כיון שאינה ראויה להקרבה],\u0006 אם כן \u0003קרא למעוטי\u0004 \u0005[כתוב\u0006 מיוחד \u0005למעט]\u0006 \u0003למה לי?\u0004 שהרי בין כה וכה אי אפשר להקריבה, ואין צורך בפסוק מיוחד לומר שאין עובר עליה ב\"בל תאחר\".","\u0003אמר רב ששת: לעולם\u0004 תפרש שבא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חילופי עולה ושלמים, והכא במאי עסקינן\u0004 \u0005[וכאן במה עוסקים אנו];\u0006 \u0003כגון שעברו עליו שני רגלים\u0004 מיום שהקדישו ולא הביאו \u0003והומם\u0004 (ונפל בו מום) \u0003וחיללו על אחר\u0004 כדין, \u0003ועבר עליו\u0004 עוד \u0003רגל אחד. סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל ו\u0004קרבן זה \u0003מכח קמא קאתי\u0004 \u0005[\u0006הקרבן \u0005הראשון הוא בא],\u0006 שהרי הוקדש כחילוף לו, ו\u0003כמאן\u0004 \u0005[\u0006ו\u0005כמי]\u0006 ש\u0003עברו עליו שלשה רגלים דמי\u0004 \u0005[ייחשב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן, ומונים לו שלושה רגלים מזמן הקדשתו.","ושואלים: \u0003זה נוח לשיטת חכמים, אולם ל\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר: כיון שעבר עליו רגל אחד עובר ב\"בל תאחר\", מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 ולפרש כאן? \u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שהומם בתוך הרגל, וחיללו\u0004 על קרבן אחר, \u0003ועבר עליו הרגל\u0004 ולא הקריבו. \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ומכח קמא קאתי\u0004 \u0005[הראשון הוא בא]\u0006 והראשון הלא הוקדש לפני הרגל — \u0003כמאן דעבר עליה כוליה רגל דמי\u0004 \u0005[כמי שעבר עליו כל הרגל נחשב],\u0006 ועובר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו כן.","שנאמר שם \u0003\"והיה בך חטא\"\u0004 ומלשון זה למדים, כי דווקא בך יהיה חטא, אולם \u0003ולא בקרבנך חטא,\u0004 שאין הקרבן נפסל על ידי הבאתו באיחור. ושואלים: \u0003והא מהכא נפקא\u0004 \u0005[ו\u0006דבר \u0005זה מכאן,\u0006 מפסוק זה, \u0005יוצא\u0006 הוא נלמד\u0005]?\u0006 הלא \u0003מ\u0004מה שלמדו \u0003אחרים נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אחרים אומרים: יכול יהא בכור שעברה שנתו\u0004 שלא הקריבוהו כפי מצוותו בתוך שנתו הראשונה, אלא לאחר מכן, \u0003כפסולי המוקדשין ויפסל\u0004 לקרבן כבעל מום —","\u0003תלמוד לומר: \"ואכלת לפני ה' אלהיך\u0004 במקום אשר יבחר לשכן שמו שם \u0003מעשר דגנך תירשך ויצהרך ובכרת בקרך וצאנך\" (דברים יד, כג), מקיש\u0004 (משווה) הפסוק \u0003בכור למעשר\u0004 דגן, \u0003מה מעשר אינו נפסל משנה לחברתה\u0004 שהרי מפורש בו שמביאים אותו עד סוף שלוש שנים, \u0003אף בכור אינו נפסל משנה לחברתה.\u0004 ואם כן יש לנו מקור להלכה שאין הקרבן עצמו נפסל משום האיחור!","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 גם לימוד נוסף זה, כי \u0003סלקא דעתך אמינא\u0004 \u0005[\u0006שמא \u0005יעלה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 שאין הקרבן נפסל אמורים דווקא ב\u0003בכור, דלאו בר הרצאה הוא\u0004 \u0005[שאינו ראוי לריצוי],\u0006 כלומר, אינו בא על מנת לכפר (\"לרצות\") על חטא כלשהו, לא על מצות עשה ולא על מצות לא תעשה, ואינו אלא מתנה לכהן, \u0003אבל קדשים\u0004 אחרים ש\u0003בני הרצאה נינהו\u0004 \u0005[ריצוי הם]\u0006 ותפקידם לכפר ולרצות על בעליהם, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא לירצו\u0004 \u0005[ירצו]\u0006 אם הביאם באיחור, לכך \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","ושואלים עוד: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 אין לימוד זה נחוץ,"],["כי דבר זה \u0003בן עזאי נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003בן עזאי אומר:\u0004 נאמר, \"לא ירצה המקריב \u0003אתו\"\u0004 (ויקרא ז, יח),","\u0003מה תלמוד לומר,\u0004 מה למדים אנו מן ההדגשה \"אותו\"? \u0003לפי שנאמר:\u0004 \"כי תידור נדר לה' אלוקיך \u0003לא תאחר לשלמו\u0004 כי דרוש ידרשנו ה' אלוקיך מעימך והיה בך חטא\" (דברים כג, כב), ומכתוב זה \u0003שומע אני\u0004 כי \u0003אף\u0004 ה\u0003מאחר\u0004 להביא את \u0003נדרו\u0004 יהא \u0003ב\"בל ירצה\", תלמוד לומר: \"אותו\"\u0004 להדגיש: \u0003אותו\u0004 קרבן פיגול שהקריבו שלא בזמנו הוא \u0003ב\"לא ירצה\", ו\u0004אולם \u0003אין\u0004 ה\u0003מאחר נדרו\u0004 עובר \u0003ב\"לא ירצה\",\u0004","\u0003אלא,\u0004 יש לדחות מה שאמרנו ולפרש את הכתוב כך: ההדגשה בכתוב \"והיה בך חטא\" באה ללמד: \u0003בך חטא\u0004 — \u0003ולא באשתך חטא.\u0004 וצריך הדבר להיאמר, שלא ייחשב הדבר כאיחור גם לבני ביתו.","כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל ואמר ר' יוחנן, ואי תימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אלעזר: אין אשתו של אדם מתה אלא אם כן מבקשין ממנו ממון\u0004 שהבטיח \u0003ואין לו\u0004 לשלם, \u0003שנאמר\u0004 לענין המחייב עצמו בממון של ערבות: \u0003\"אם אין לך לשלם למה יקח משכבך מתחתיך\"\u0004 (משלי כב, כז), ונתפרש כרמז למות אשתו, ואם כן \u0003אימא בהאי עון\u0004 \u0005[אמור שבעון זה]\u0006 של \u0003\"בל תאחר\" נמי\u0004 \u0005[גם כן]\u0006 \u0003אשתו מתה,\u0004 שאף זה כמי שאינו רוצה לפרוע התחייבותו, לכך \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב שאין הדבר כן, ועבירה זו נחשבת רק לו לבדו.","על הכתוב \"מוצא שפתיך תשמור ועשית כאשר נדרת לה' אלוהיך נדבה אשר דברת בפיך\" (דברים כג, כד), \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"מוצא שפתיך\"\u0004 — \u0003זו מצות עשה, \"תשמר\"\u0004 — \u0003זו מצות לא תעשה,\u0004 שלשון שמירה היא אזהרה מעבירה, \u0003\"ועשית\"\u0004 — הרי זו \u0003אזהרה לבית דין שיעשוך\u0004 (שיגרמו לך שתעשה) שיכריחוך לכך, \u0003\"כאשר נדרת\"\u0004 — \u0003זה נדר, \"לה' אלהיך\"\u0004 — \u0003אלו חטאות ואשמות עולות\u0004 (ראיה) \u0003ושלמים\u0004 (שלמי חגיגה) לקיים דבריו, שהם שאר קרבנות שקיימת חובה עליו להביאם, \u0003\"נדבה\"\u0004 — \u0003כמשמעו, \"אשר דברת\"\u0004 — \u0003אלו קדשי בדק הבית,\u0004 שאומר דברו ונודר, \u0003\"בפיך\"\u0004 — \u0003זו צדקה,\u0004 שמחייב את עצמו כשמבטיח בפיו.","ומעתה באים לביאור פרטי הדברים, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"מוצא שפתיך\"\u0004 — \u0003זו מצות עשה.\u0004 ושואלים: \u0003למה לי\u0004 לשם מה נאמר, והלא \u0003מ\"ובאת שמה... והבאתם שמה\"\u0004 (דברים יב, ה-ו) \u0003נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005]\u0006 שזו מצות עשה! וכן \u0003\"תשמר\"\u0004 ששנינו כי \u0003זו מצות לא תעשה, למה לי?\u0004 הלא \u0003מ\u0004מה שנאמר \u0003\"לא תאחר לשלמו\" נפקא\u0004 \u0005[יוצא\u0006 נלמד הדבר\u0005]!\u0006","וכן \u0003\"ועשית\"\u0004 ששנינו כי זו \u0003אזהרה לבית דין שיעשוך. למה לי?\u0004 הלא \u0003מ\"יקריב אתו\"\u0004 (ויקרא א, ג) \u0003נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 כתוב זה שנאמר \u0003\"יקריב אתו\"\u0004 (ויקרא א, ג), \u0003מלמד שכופין אותו\u0004 להקריב את קרבנו. \u0003יכול\u0004 שיהא מקריבו אפילו \u0003בעל כרחו\u0004 לגמרי — \u0003תלמוד לומר: \"לרצנו\"\u0004 (ויקרא א, ג), \u0003הא כיצד\u0004 עושים? בית דין \u0003כופין אותו עד שיאמר רוצה אני.\u0004 וכיון שכל ההלכות הללו כבר ידועות ממקור אחר מה טעם לחזרה זו?","ומשיבים: יש צורך בדבר כי מדובר במקרים שונים. \u0003חד\u0004 \u0005[\u0006במקום \u0005אחד]\u0006 מדובר באופן ש\u0003אמר\u0004 ונדר קרבן, \u0003ו\u0004אולם \u0003לא אפריש\u0004 \u0005[הפריש\u0006 אותו\u0005]\u0006 ולא ייחד בעל חיים מסויים לנדרו, \u0003וחד\u0004 \u0005[ו\u0006במקום \u0005אחד]\u0006 מדובר כאשר \u0003אפריש\u0004 \u0005[הפריש]\u0006 את הקרבן, \u0003ו\u0004אולם \u0003לא אקריב\u0004 \u0005[הקריב\u0006 אותו\u0005].\u0006","\u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שניהם, \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק במקרה ש\u0003אמר ולא אפריש\u0004 \u0005[הפריש]\u0006 כלל, היינו אומרים שנענש \u0003משום\u0004 ש\u0003לא קיימיה לדיבוריה\u0004 \u0005[קיים את דיבורו],\u0006 \u0003אבל\u0004 אם \u0003אפריש\u0004 \u0005[הפריש]\u0006 \u0003ולא אקריב\u0004 \u0005[הקריב]\u0006 \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003כל היכא דאיתיה\u0004 \u0005[כל מקום שהוא נמצא]\u0006 — \u0003בי גזא דרחמנא איתיה\u0004 \u0005[בבית אוצרו של הקדוש ברוך הוא, הוא נמצא]\u0006 שהרי הארץ ומלואה לה', ולכן אינו עובר אם מאחר את הבאתו למקדש, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 ללמדנו שגם במקרה זה עובר.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 \u0003אפריש\u0004 \u0005[הפריש]\u0006 \u0003ולא אקריב\u0004 \u0005[הקריב],\u0006 הייתי אומר שעובר משום שיש כבר קרבן בעין \u0003דקא משהי ליה גביה\u0004 \u0005[שמשהה אותו אצלו],\u0006 \u0003אבל\u0004 אם \u0003אמר\u0004 נדר \u0003ולא אפריש\u0004 \u0005[הפריש],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003דיבורא\u0004 \u0005[דיבור]\u0006 בלבד \u0003לא כלום הוא,\u0004 כל עוד לא היתה הפרשה במעשה, ולכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","ומקשים: \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר]\u0006 שמדובר באופן ש\u0003אמר\u0004 בלבד \u0003ולא אפריש\u0004 \u0005[הפריש]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003נדבה\u0004 כבר \u0003כתיבא\u0004 \u0005[כתובה],\u0006 שהלא היא נלמדת בגזירה שווה, \u0003ותנן\u0004 \u0005[ושנינו במשנה]:\u0006 \u0003אי זהו נדר\u0004 — \u0003האומר: הרי עלי עולה,\u0004 שחייב את עצמו להביא קרבן. \u0003ואי זו היא נדבה\u0004 — \u0003האומר: הרי זו,\u0004 בהמה מסויימת, תהא ל\u0003עולה.\u0004","\u0003ומה בין נדר לנדבה\u0004 לענין הלכה? ב\u0003נדר,\u0004 אם \u0003מת או נגנב\u0004 — בעל החיים שנדר \u0003חייב באחריותו\u0004 וצריך להביא אחר במקומו, שהרי היתה על הנודר התחייבות אישית להביא. ואילו ב\u0003נדבה,\u0004 אם \u0003מתה או נגנבה\u0004 הבהמה — \u0003אינו חייב באחריותה.\u0004 ואם כן, נדבה היא קרבן שאדם הפרישו כבר!","\u0003אמר רבא: משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות לנדר כעין נדבה, \u0003כגון\u0004 באופן ש\u0003אמר: הרי עלי עולה על מנת שאיני חייב באחריותה\u0004 ובאופן כזה אינה אלא נדבה.","שנינו בברייתא \u0003\"בפיך\"\u0004 — \u0003זו צדקה. אמר רבא: וצדקה,\u0004 אם מאחר בנתינתה לאחר שנדרה — \u0003מחייב עלה לאלתר\u0004 \u0005[מתחייב עליה מיד].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003דהא קיימי\u0004 \u0005[שהרי\u0006 כרגיל \u0005עומדים,\u0006 מצויים\u0005]\u0006 \u0003עניים\u0004 מיד בשעת הנדר, ויש אפשרות לתת להם מיד, שלא כקרבן שאינו יכול להקריבו אלא בבית המקדש.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 דין זה! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 סברה הפוכה; \u0003כיון דבעניינא\u0004 \u0005[שבענין]\u0006 ה\u0003קרבנות כתיבא\u0004 \u0005[כתובה\u0006 הצדקה\u0005],\u0006 ושמא \u0003עד דעברי עלה\u0004 \u0005[שיעברו עליה]\u0006 \u0003שלשה רגלים כקרבנות\u0004 לא יעבור ב\"בבל תאחר\", על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבא שאינו כן, כי \u0003התם היא דתלינהו רחמנא\u0004 \u0005[שם\u0006 בקרבנות, \u0005הוא שתלתה אותם התורה]\u0006 \u0003ברגלים, אבל הכא\u0004 \u0005[כאן]\u0006 בצדקה \u0003לא,\u0004 וטעם הדבר, \u0003דהא שכיחי\u0004 \u0005[שהרי מצויים]\u0006 \u0003עניים.\u0004","\u0003אמר רבא:\u0004 אף על פי שלרוב הדעות בנדרים אינו עובר על \"בל תאחר\" אלא לאחר שלושה רגלים, מכל מקום, \u0003כיון שעבר עליו רגל אחד\u0004 שלא הביא נדריו — מיד \u0003עובר בעשה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003העיד ר' יהושע ור' פפייס על ולד\u0004 שנולד לבהמת \u0003שלמים,\u0004 בין אם הקדישה לפני שנתעברה ובין אם הקדישה לאחר מכן, \u0003שיקרב\u0004 אף הוא \u0003שלמים. אמר ר' פפייס: אני מעיד שהיתה לנו פרה של זבחי שלמים ואכלנוה בפסח, ואכלנו ולדה\u0004 של אותה פרה כקרבן \u0003שלמים בחג\u0004 (סוכות). ונברר את פרטי אותו מעשה.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בפסח\u0004 עצמו \u0003לא אקרבוה\u0004 \u0005[הקריבוהו]\u0006 את הולד, \u0003אימור\u0004 \u0005[אמור]\u0006 שמא \u0003מחוסר זמן הוה\u0004 \u0005[היה]\u0006 שעוד לא הגיע ליום השמיני לחייו, ואסור להקריב בהמה לפני כן. \u0003אלא ולדה בעצרת\u0004 (חג השבועות) \u0003היכי משהי לה\u0004 \u0005[איך משהים אותו]\u0006 ולא מקריבים אותו מיד בחג הסמוך לפסח? והלא לדברי רבא \u0003עברי עליה\u0004 \u0005[עוברים עליו,\u0006 על איחורו\u0005]\u0006 \u0003בעשה\u0004 מיד בחלוף החג הראשון!","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 \u0003של רבא: כגון\u0004"],["\u0003שהיה\u0004 ולד זה \u0003חולה בעצרת\u0004 (חג השבועות) ולכן לא הביאוהו אלא ברגל הבא. \u0003רב אשי אמר\u0004 תירוץ אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואכלנו ולדה שלמים בחג\" דקתני\u0004 \u0005[ששנה]\u0006 — כוונתו ל\u0003חג השבועות,\u0004 ואם כן אין כל קושי בדבר.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 רב זביד שלא פירש כן, מה טעמו — \u0003כל היכא דתני\u0004 \u0005[מקום שהוא שונה]\u0006 ומכנה את שם החג \u0003'פסח', תני\u0004 \u0005[הריהו שונה]\u0006 ומכנה את חג השבועות בשם \u0003'עצרת'\u0004 ואין מכנים בשם 'חג' סתם אלא לחג הסוכות.","\u0003אמר רבא: כיון שעברו עליו שלשה רגלים\u0004 ולא הביא, הרי \u0003בכל יום ויום\u0004 מאז \u0003עובר עליו ב\"בל תאחר\". מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בתוספתא: \u0003אחד בכור, ואחד כל הקדשים, כיון שעברו עליהם שנה\u0004 אפילו \u0003בלא\u0004 שיעברו שלוש ה\u0003רגלים\u0004 או שעברו שלוש \u0003רגלים בלא\u0004 שעברה \u0003שנה\u0004 שלימה — \u0003עובר ב\"בל תאחר\".\u0004","ותחילה תוהים על השאלה עצמה: \u0003והאי מאי תיובתיה\u0004 \u0005[וזה מה קושיתו]?\u0006 הרי לכאורה אין כל קשר בין הלכה זו ודברי רבא, ומה הקושיה שבדבר? \u0003אמר רב כהנא: מאן דקא מותיב\u0004 \u0005[מי שמקשה\u0006 כאן\u0005]\u0006 — \u0003שפיר קא מותיב\u0004 \u0005[יפה הוא מקשה].\u0006 וכך יש להבין: \u0003מכדי תנא אלאוי קא מהדר\u0004 \u0005[הרי התנא\u0006 בתוספתא זו \u0005על\u0006 הוספת \u0005לאוים הוא מחזר],\u0006 כלומר, בא להראות תוספת איסור, אפילו בשנה בלא רגלים או רגלים בלא שנה, ואם דברי רבא נכונים להלכה, אם כן \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003בכל יום ויום עובר ב\"בל תאחר\".\u0004","\u0003ואידך\u0004 \u0005[והאחר]\u0006 רבא מה הוא אומר — \u0003תנא\u0004 זה \u0003למיקבעיה בלאו קא מהדר\u0004 \u0005[לקבוע את הדבר באיסור הוא מחזר],\u0006 כלומר, אינו בא אלא להגדיר את תחומי איסור זה, אולם \u0003בלאוי יתירי לא קא מהדר\u0004 \u0005[\u0006להוסיף \u0005לאוים יתרים אין הוא מחזר].\u0006","כיון שהזכרנו ברייתא זו, באים לבררה ל\u0003גופא,\u0004 שנינו: \u0003אחד בכור ואחד כל הקדשים, כיון שעברו עליהם שנה בלא רגלים\u0004 או \u0003רגלים בלא שנה\u0004 — \u0003עובר ב\"בל תאחר\".\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רגלים בלא שנה משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 שיתכן שיעברו שלוש רגלים (מפסח עד סוכות) שהם רק כמחצית השנה, \u0003אלא שנה בלא רגלים היכי משכחת לה\u0004 \u0005[האיך אתה מוצא אותה]\u0006 אפשרות שתעבור שנה שלימה ועדיין לא עברו שלוש רגלים?","ומוסיפים: \u0003הניחא למאן דאית ליה\u0004 \u0005[זה נוח למי שיש לו,\u0006 שסבור\u0005],\u0006 שעובר על שלוש רגלים דווקא \u0003כסדרן,\u0004 הרי \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה],\u0006 שאם נדר סמוך לחג השבועות לא יעבור אלא לאחר חג הסוכות בשנה השלישית ויתכן איפוא שתעבור שנה שלימה בלא שיעברו שלוש רגלים (כסידרן). \u0003אלא למאן דלית ליה\u0004 \u0005[למי שאין לו]\u0006 שאינו מקבל את ההלכה שחובה שיהיו \u0003כסדרן, היכי משכחת לה\u0004 \u0005[היאך מוצא אתה אותה]?\u0006","ומעירים עוד: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004פי שיטת \u0003רבי משכחת לה\u0004 \u0005[מוצא אתה\u0006 אפשרות \u0005כזו]\u0006 \u0003בשנה מעוברת,\u0004 שלדעתו חודש העיבור אינו נחשב חלק מן השנה, חוץ מאחד עשר יום ששנת החמה ארוכה מזו של הלבנה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006נאמר בענין מוכר בית בעיר חומה שהמוכר יכול לגאלו בחזרה עד \"עד תום שנת ממכרו\" (ויקרא כה, כט), \"ואם לא יגאל עד מלאת לו שנה תמימה וקם הבית אשר בעיר אשר לו חומה לצמיתות לקונה אותו לדורותיו לא יצא ביובל\" (ויקרא כה, ל), ונחלקו בפירוש המושג \u0003\"שנה תמימה\"; רבי אומר, מונה שלש מאות וששים וחמשה יום כמנין ימות החמה,\u0004 ולא שנת לבנה כרגיל, ולכן קורא לה \"שנה תמימה\",","\u0003וחכמים אומרים: מונה שנים עשר חודש מיום ליום,\u0004 כלומר, מיום מסויים בחודש עד לאותו יום כעבור שנים עשר חודש, \u0003ואם נתעברה שנה\u0004 — \u0003נתעברה לו\u0004 למוכר, והדבר הוא עדיין בתוך גדר \"שנה תמימה\". ומעתה \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות \u0003ל\u0004שיטת \u0003רבי,\u0004 כיצד: \u0003דאקדשה בתר\u0004 \u0005[שהקדיש אותה,\u0006 את הבהמה \u0005אחר]\u0006 \u0003חג המצות, דכי מטא שילהי\u0004 \u0005[ולכאשר מגיע סוף]\u0006 \u0003אדר בתראה\u0004 \u0005[האחרון,\u0006 אדר שני\u0005]\u0006 \u0003שנה מליא\u0004 \u0005[מלאה],\u0006 אולם \u0003רגלים לא מלו\u0004 \u0005[נתמלאו],\u0006 שהרי עדיין לא הגיע הרגל השלישי. \u0003אלא לרבנן, היכי משכחת לה\u0004 \u0005[לחכמים, כיצד מוצא אתה אותה]?\u0006","ומשיבים: \u0003כדתני\u0004 \u0005[כפי ששנה]\u0006 \u0003רב שמעיה: עצרת\u0004 (חג השבועות) \u0003פעמים\u0004 הוא חל ב\u0003חמשה\u0004 בסיון, \u0003פעמים\u0004 ב\u0003ששה\u0004 בסיון, \u0003ופעמים\u0004 ב\u0003שבעה. הא כיצד?\u0004 אם \u0003שניהן,\u0004 גם ניסן וגם אייר, היו \u0003מלאין\u0004 (בני שלושים יום) נמצא שיום החמישים לפסח, שבו נקבע חג השבועות הוא \u0003חמשה\u0004 בסיון, אם היו \u0003שניהן חסרין\u0004 — הריהו ב\u0003שבעה\u0004 בסיון, \u0003אחד מלא ואחד חסר\u0004 — הרי זה \u0003בששה.\u0004 ואם כן לשיטה זו, אם היו שניהם מלאים וחל חג השבועות בחמישה בסיון, ונדר הוא בשישה בסיון שהיה יום אחר חג השבועות באותה שנה, ובשנה שלאחריה היו שניהם חסרים וחל החג בשבעה בסיון הרי שעברה שנה ולא עברו שלושה רגלים.","ומעירים: \u0003ומאן\u0004 \u0005[ומי\u0006 הוא\u0005]\u0006 \u0003תנא\u0004 זה \u0003דפליג עליה\u0004 \u0005[החולק עליו]\u0006 על \u0003רב שמעיה\u0004 וסבור שלשנה יש מנין ימים קבוע — \u0003אחרים היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אחרים אומרים: אין בין עצרת לעצרת\u0004 בשנה הבאה וכן \u0003אין בין ראש השנה לראש השנה\u0004 שלאחריו \u0003אלא ארבעה ימים בלבד,\u0004 לפי שמנין ימות השנה קבוע הוא (354 יום) והחודשים באים כסדרם אחד מלא ואחד חסר, \u0003ואם היתה שנה מעוברת\u0004 — והם איפוא חמישים ושנים שבועות שלמים וארבעה ימים נוספים הרי בשל חודש אדר הנוסף נוסף יום אחד על ארבעה שבועות שלמים, ולכך הרי הם \u0003חמשה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: יורש מהו ב\"בל תאחר\"?\u0004 כלומר, האם יורש עובר משום \"בל תאחר\" על נדר שנדר אביו? וצדדי השאלה: \u0003\"כי תדר נדר\u0004 לה' אלוקיך לא תאחר לשלמו \u0003\"(דברים כג, כב) אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 יורש זה עצמו \u0003לא נדר\u0004 דבר, \u0003או דלמא\u0004 \u0005[שמא]\u0006 עיקרה של המצוה היא כפי שנאמר: \u0003\"ובאת שמה והבאתם שמה\"\u0004 (דברים יב, ה-ו) \u0003ו\u0004בהבאת הקרבן בזמנו \u0003הא מיחייב\u0004 \u0005 [הרי הוא מחוייב].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003תשובה לדבר, דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא:\u0004 נאמר \"כי דרוש ידרשנו ה' אלהיך \u0003מעמך\"\u0004 (דברים כג, כב) ומ\"עמך\" כוונתו \u0003פרט ליורש.\u0004 ומכאן נלמד שאין היורש עובר ב\"בל תאחר\".","ותוהים: \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003\"מעמך\"\u0004 הלא \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 לענין אחר, כי דבר \u0003זה\u0004 מלמדנו לענין \u0003לקט שכחה ופאה\u0004 שאף עליהם עובר ב\"בל תאחר\"! ומשיבים: \u0003קרי ביה\u0004 \u0005[קרא בו],\u0006 כלומר, למד ממנו שני לימודים, מ\u0003\"עמך\"\u0004 ומ\u0003\"מעמך\";\u0004 ממה שנאמר \"עמך\" נלמד לענין לקט שכחה ופאה, וה־'מ' הנוספת \"מעמך\" באה למעט יורש.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא\u0004 שאלה אחרת בנושא זה: \u0003אשה\u0004 שנדרה נדר \u0003מה היא,\u0004 מה דינה, \u0003ב\u0004ענין דין \u0003\"בל תאחר\"?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא מיחייבא\u0004 \u0005[אינה מחוייבת]\u0006 \u0003בראיה\u0004 של המקדש ברגל (שהרי היא מצוות עשה שהזמן גרמא, שנשים פטורות ממנה), ולכן אינה עוברת אם אינה מביאה את הקרבן בזמנו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר \u0003הא איתה\u0004 \u0005[הרי היא ישנה]\u0006 ומחוייבת \u0003ב\u0004מצות ה\u0003שמחה\u0004 בחג, וכיון שכך מסתבר לומר שהיא מחוייבת גם בשאר מצוות הקשורות בחג?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ותיפוק ליה\u0004 \u0005[ושיצא לו\u0006 הדבר\u0005]\u0006 בפשטות \u0003דהא איתה\u0004 \u0005[שהרי היא ישנה]\u0006 ומחוייבת גם כן בשמחת החג, ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר אביי הכי\u0004 \u0005[כך]\u0006 שמצות עשה לאשה לשמוח ברגל? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: אשה\u0004 — \u0003בעלה משמחה.\u0004 כלומר, אין מצוה על האשה עצמה לשמוח, אלא המצוה חלה על הבעל — לגרום לכך שתהא אשתו שמחה בחג. ומשיבים: \u0003ל\u0004פי \u0003דבריו\u0004 של \u0003ר' זירא קאמר\u0004 \u0005[אמר]\u0006 ועל פי שיטתו, שכיון שר' זירא סבור שיש מצות עשה על האשה בשמחה — הרי נפתרת שאלתו על פי שיטתו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003בכור מאימתי מונין לו שנה\u0004 לענין \"בל תאחר\"? \u0003אביי אמר: משעה שנולד, רב אחא בר יעקב אמר: משעה שנראה להרצאה.\u0004 כלומר, משעה שהיה ראוי לקרבן והוא מיום השמיני והלאה, כמפורש בתורה (ויקרא כב, כז).","ומעירים, \u0003ולא פליגי\u0004 \u0005[ו\u0006באמת \u0005אינם חלוקים]\u0006 בהלכה, כי \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב אחא בר יעקב שמונין לו משעה שנרצה, מדובר \u0003ב\u0004בכור \u0003תם,\u0004 שאין בו מום, וחובה היא להביאו ולהקריבו במקדש."],["ואילו \u0003הא\u0004 \u0005[זה\u0006 שאמר אביי\u0005],\u0006 מדובר \u0003בבעל מום,\u0004 שמכיון שנולד במומו הרי הוא ראוי להישחט כבר מיום הוולדו, ולכן אם אינו נותנו לכהן תוך שנה מאותו יום הריהו עובר ב\"בל תאחר\".","ושואלים: \u0003בעל מום\u0004 מעיקרו \u0003מי מצי אכיל ליה\u0004 \u0005[האם יכול הוא לאכול אותו]\u0006 מיד? והרי יש לחשוש שמא הוא נפל, ואין שחיטה מועילה לו עד שיחיה שמונה ימים שזהו זמן ההבחנה בבהמה שאינה נפל (ראה שבת קלה, ב)! ומשיבים: \u0003דקים ליה ביה\u0004 \u0005[שמוחזק לו בו]\u0006 \u0003ש\u0004כבר \u0003כלו לו חדשיו,\u0004 אחר שהוא יודע בבירור את זמן עיבורה המדוייק של הבהמה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003באחד בניסן ראש השנה ל\u0004מנין ה\u0003חדשים\u0004 של השנה, \u0003ולעיבורין, ולתרומת שקלים,\u0004 שאין קונים בהמות לקרבנות ציבור בכל שנה אלא מן השקלים שנתרמו באותה שנה, ומראש חודש ניסן הריהי נחשבת כשנה חדשה. \u0003ויש אומרים אף לשכירות בתים.\u0004","ומפרטים: \u0003לחדשים מנלן\u0004 \u0005[מניין לנו]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"החדש הזה לכם ראש חדשים ראשון הוא לכם לחדשי השנה. דברו אל כל עדת ישראל לאמר בעשר לחדש הזה ויקחו להם איש שה לבית אבת שה לבית. והיה לכם למשמרת עד ארבעה עשר יום לחדש הזה ושחטו אתו וגו'\"\u0004 (שמות יב, ב-ג. ושמות יב, ו) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"שמור את חדש האביב\u0004 ועשית פסח לה' אלוקיך כי בחודש האביב הוציאך ה' ממצרים לילה\u0003\"\u0004 (דברים טז, א), \u0003איזהו חדש שיש בו אביב\u0004 (והוא — השעורה הבשלה), \u0003הוי אומר\u0004 — \u0003זה ניסן, וקרי ליה\u0004 \u0005[וקורא הוא אותו]\u0006 חודש \u0003ראשון,\u0004 משמע שהוא ראשון לחודשי השנה.","ושואלים: \u0003ואימא\u0004 \u0005[ושמא]\u0006 חודש \u0003אייר\u0004 הוא זה? ומשיבים: \u0003בעינא\u0004 \u0005[צריכים]\u0006 חודש שיהיה בו \u0003אביב, וליכא\u0004 \u0005[ואין\u0006 כבר\u0005]\u0006 באייר, שכבר נקצרה השעורה. ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהוא חודש \u0003אדר\u0004 שחלק מן השעורה מתחיל להבשיל בו\u0003!\u0004 ומשיבים: \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שיהיה \u0003רוב אביב\u0004 בחודש זה, \u0003וליכא\u0004 \u0005[ואין]\u0006 עדיין, כי רוב השעורה מתבשלת בחודש ניסן. ותוהים: \u0003מידי [וכי] \"רוב אביב\" כתיב\u0004 \u0005[נאמר]:\u0006 בפסוק? הלא \"אביב\" בלבד נאמר, וכיון שיש אביב גם באדר מדוע לא נאמר שהוא החודש הראשון?","\u0003אלא אמר רב חסדא:\u0004 יש לדחות מה שאמרנו, ו\u0003מהכא\u0004 \u0005[מכאן]\u0006 למדים אנו דבר זה, שנאמר: \u0003\"אך בחמשה עשר יום לחדש השביעי באספכם את תבואת הארץ\"\u0004 (ויקרא כג, לט), \u0003איזהו חדש שיש בו אסיפה\u0004 של כל התבואות מן השדה, טרם בוא הגשם — \u0003הוי אומר זה תשרי, וקא קרי ליה\u0004 \u0005[והוא קורא אותו]\u0006 \u0003\"שביעי\",\u0004 ומכאן שהראשון הוא ניסן.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהוא חודש \u0003מרחשון ומאי \"שביעי\"\u0004 שנאמר — \u0003שביעי ל\u0004חודש \u0003אייר!\u0004 ודוחים: \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שיהא בו \u0003אסיף, וליכא\u0004 \u0005[ואין בו]\u0006 במרחשון אסיף, לפי שאז כבר נגמר האסיף ומתחילים בחרישת השדות טרם בוא הגשמים. ומקשים עוד: \u0003ואימא\u0004 \u0005[אמור]\u0006 שהוא חודש \u0003אלול\u0004 שבו כבר מתחילים לאסוף את התבואה מן השדות, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"שביעי\"\u0004 — \u0003שביעי ל\u0004חודש \u0003אדר!\u0004 ומשיבים: \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 שיהא \u0003רוב אסיף\u0004 בחודש זה, \u0003וליכא\u0004 \u0005[ואין].\u0006 ומקשים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"רוב אסיף\" כתיב\u0004 \u0005[נאמר\u0006 בכתוב\u0005]?\u0006","\u0003אלא אמר רבינא\u0004 יש לדחות מה שאמרנו, ולומר כי \u0003דבר זה מתורת משה רבינו לא למדנו\u0004 במפורש, אלא \u0003מדברי קבלה\u0004 (מדברי הנביאים) \u0003למדנו\u0004 אותו, שהרי נאמר: \u0003\"ביום עשרים וארבעה לעשתי עשר חדש הוא חדש שבט\"\u0004 (זכריה א, ז), ומתוך שחודש שבט הוא החודש האחד עשר, הרי שהראשון הוא ניסן. \u0003רבה בר עולא אמר מהכא\u0004 \u0005[מכאן],\u0006 ממקרא זה, שנאמר: \u0003\"ותלקח אסתר אל המלך אחשורוש אל בית מלכותו בחדש העשירי הוא חדש טבת\" (אסתר ב, טז).\u0004","\u0003רב כהנא אמר מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"בארבעה לחדש התשעי בכסלו\"\u0004 (זכריה ז, א). \u0003רב אחא בר יעקב אמר מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ויקראו סופרי המלך בעת ההיא בחדש השלישי הוא חדש סיון\"\u0004 (אסתר ח, ט). \u0003רב אשי אמר מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"הפיל פור הוא הגורל לפני המן מיום ליום ומחדש לחדש שנים עשר הוא חדש אדר\"\u0004 (אסתר ג, ז). \u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור\u0006 כי הדבר נלמד \u0005מכאן]:\u0006 \u0003\"בחדש הראשון הוא חדש ניסן\"\u0004 (אסתר ג, ז).","ותוהים: \u0003וכולהו, מאי טעמא\u0004 \u0005[וכולם, מה טעם]\u0006 \u0003לא אמרי מהאי\u0004 \u0005[אמרו,\u0006 למדו \u0005מזה]\u0006 מפסוק מפורש שנאמר בו איזה הוא החודש הראשון! ומשיבים: \u0003דלמא מאי\u0004 \u0005[שמא מה\u0006 פירושו\u0005]\u0006 של \u0003\"ראשון\" —\u0004 כגון \u0003ראשון למילתיה\u0004 \u0005[לעניינו],\u0006 לענין חודשי הגזירה, ואין ללמוד מכאן למקומו בתוך מנין חדשי השנה.","ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 במשנתנו, מה טעם לא מנה אף את ראש חודש ניסן כראש לחודשים? ומשיבים: \u0003ב\u0004ראשי \u0003שנים קמיירי\u0004 \u0005[הוא עוסק]\u0006 אולם \u0003ב\u0004ענין ה\u0003חדשים לא קמיירי\u0004 \u0005[אינו עוסק].\u0006","\u0003שנינו באותה ברייתא שראש חודש ניסן הוא ראש השנה לעיבורין.\u0004 ושואלים: \u0003וכי לעיבורין מניסן מנינן\u0004 \u0005[מונים אנו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מעברין\u0004 את \u0003השנה לפני ראש השנה, ואם עיברוה\u0004 — \u0003אינה מעוברת. אבל מפני הדחק\u0004 משום גזירות וסיבות אחרות — \u0003מעברין אותה אחר ראש השנה מיד\u0004 שאז חכמים מחליטים על העיבור לפי החישובים שהם עושים. \u0003ואף על פי כן אין מעברין\u0004 כלומר, אין מוסיפין את החודש היתר \u0003אלא\u0004 חודש \u0003אדר.\u0004 ואם כן, מה מקום לניסן כאן?","\u0003אמר רב נחמן בר יצחק: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003עיבורין\u0004 כאן — \u0003הפסקת עיבורין.\u0004 כלומר שבחודש ניסן שוב אין מעברים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הן,\u0004 ר' יהושע ור' פפייס, \u0003העידו שמעברין\u0004 את \u0003השנה כל\u0004 חודש \u0003אדר. שהיו\u0004 חכמים \u0003אומרים\u0004 שאין מעברים אלא \u0003עד הפורים.\u0004 ואם לא החליטו חכמי הדור לעבר את השנה קודם פורים — שוב אין מעברים.","ומסבירים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה טעמו של מי שאומר]\u0006 שאין מעברים את השנה אלא \u0003עד הפורים? כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שואלין בהלכות הפסח קודם לפסח שלשים יום,\u0004 הרי שמפורים והלאה כבר התחילו ללמד את העם את דיני הפסח שהוא שלושים יום לאחר פורים, ואם יעברו את השנה לאחר הפורים יידחה חג הפסח בחודש, וכתוצאה מכך \u0003אתי לזלזולי\u0004 \u0005[יבואו לזלזל]\u0006 \u0003בחמץ,\u0004 שכיון שכבר שמעו מן הדרשנים שהפסח אמור לחול חודש לאחר הפורים, שוב לא יתקבלו אצלם דברי שלוחי בית הדין הבאים לאחר מכן ולפיהם יש לדחות את הפסח בחודש נוסף.","\u0003ואידך\u0004 \u0005[והאחרים]\u0006 שאינם חוששים לכך — \u0003מידע ידיע דשתא מעברתא בחושבנא תליא מלתא\u0004 \u0005[ידוע כי שנה מעוברת בחשבון תלוי הדבר]\u0006 \u0003וסברי: חושבנא הוא דלא סליק להו לרבנן עד האידנא\u0004 \u0005[וסבורים שהחשבון הוא שלא עלה להם לחכמים עד עכשיו]\u0006 וסיימו את חישוביהם רק לאחר פורים. וכיון שהכל יודעים את הדבר אין לחשוש לזלזול בפסח.","ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 שלא מנה את אחד בניסן כראש השנה לענין עיבור השנה, מה טעמו? ומסבירים: הוא \u0003ב\u0004דברים שראש חודש ניסן הוא \u0003התחלה\u0004 להם \u0003קמיירי\u0004 \u0005[עוסק],\u0006 ואולם \u0003בהפסקה\u0004 הוא \u0003לא קמיירי\u0004 \u0005[עוסק],\u0006 והרי לענין העיבור אין ראש חודש ניסן ראש שנה אלא מועד אחרון.","שנינו בברייתא שאחד בניסן הוא ראש השנה \u0003לתרומת שקלים.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר ר' יאשיה: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"זאת עולת חדש בחדשו לחדשי השנה\"\u0004 (במדבר כח, יד), ופירוש ריבוי צורות המלה \"חדש\" שבפסוק — \u0003אמרה תורה: חדש והבא קרבן מתרומה חדשה\u0004 בשנה החדשה. \u0003וגמרי\u0004 \u0005[ולומדים]\u0006 בגזירה שווה \u0003\"שנה\" \"שנה\" מניסן,\u0004 שלענין זה מתחילה השנה בניסן. שבניסן נאמר: \u0003\"ראשון הוא לכם לחדשי השנה\"\u0004 (שמות יב, ב).","ומקשים: \u0003ולגמור\u0004 \u0005[ושילמד]\u0006 גזירה שווה \u0003\"שנה\" \"שנה\" מתשרי\u0004 שנאמר בו \u0003\"מראשית השנה\"\u0004 (דברים יא, יב)! ומשיבים: \u0003דנין שנה שיש עמה חדשים\u0004 (והיא \"עולת חודש בחדשו\") \u0003משנה שיש עמה חדשים\u0004 כפי שנאמר ש\"ראשון הוא לחדשי השנה\", \u0003ואין דנין שנה שיש עמה חדשים משנה שאין עמה חדשים\u0004 (\"ראשית השנה\" בלבד).","באותה הלכה \u0003אמר רב יהודה אמר שמואל: קרבנות צבור הבאין באחד בניסן\u0004 — \u0003מצוה להביא מן החדש,\u0004 כלומר, מתרומה שהביאו לצורך שנה זו. \u0003ואם הביא מן הישן\u0004 — \u0003יצא\u0004 ידי חובת הקרבנות, \u0003אלא שחיסר מצוה\u0004 של חידוש מתרומה חדשה.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003קרבנות צבור הבאין באחד בניסן\u0004 — \u0003מצוה להביא מן החדש, ואם הביא מן הישן\u0004 — \u0003יצא, אלא שחיסר מצוה.\u0004 ועוד שנינו שם: \u0003ויחיד שהתנדב\u0004 להביא קרבנות ציבור \u0003משלו\u0004 — \u0003כשרין, בלבד שימסרם לצבור\u0004 ולא ישאיר את הקרבן ברשותו.","על כך תוהים: דבר זה הלא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שיכול אדם להתנדב משלו לציבור, אם אמנם נתן לציבור כראוי. ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש\u0004 \u0005[שנחשוש]\u0006 לאותו אדם \u0003שמא\u0004"],["\u0003לא ימסרם לצבור יפה יפה\u0004 ובלבו יתכוון שישארו ברשותו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לחשוש לכך.","ושואלים: \u0003ותנא דידן\u0004 \u0005[והתנא שלנו]\u0006 מדוע לא מנה תרומת שקלים בין ענייני ראש חודש ניסן? ומשיבים: התנא שלנו אינו מביא אלא דברים שהם מוחלטים, \u0003כיון דקתני\u0004 \u0005[ששנינו]\u0006 \"ש \u0003אם הביא\u0004 מן התרומה הישנה \u0003יצא\u0004 בדיעבד\" \u0003— אם כן לא פסיקא ליה\u0004 \u0005[אין\u0006 הדבר \u0005פסוק,\u0006 \u0003מוחלט\u0004\u0005],\u0006 ולכך לא שנה זאת.","שנינו בברייתא כי \u0003יש אומרים\u0004 שאחד בניסן הוא ראש השנה \u0003אף לשכירות בתים. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המשכיר בית לחבירו לשנה\u0004 — \u0003מונה שנים עשר חודש מיום ליום. ואם אמר\u0004 שהוא משכיר \u0003\"לשנה זו\", אפילו לא עמד\u0004 (נעשה) הסכם זה \u0003אלא באחד באדר, כיון שהגיע יום אחד בניסן\u0004 — \u0003עלתה לו שנה,\u0004 ונסתיים חוזה השכירות.","ומעירים: \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003יום אחד בשנה חשוב שנה,\u0004 מכל מקום \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 בדיני שכירות בתים \u0003דלא טרח איניש למיגר ביתא לבציר מתלתין יומין\u0004 \u0005[שאין אדם טורח לשכור בית לפחות משלושים יום]\u0006 ולכן אם שכר לאחר ראש חודש אדר אין מחשיבים זאת לשנה שלימה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003תשרי\u0004 הוא ראש השנה לענין שכירות בתים ואם שוכר אדם דירה בקיץ תסתיים השנה בחודש תשרי? ומשיבים: \u0003סתם, כי אגר איניש ביתא\u0004 \u0005[כאשר שוכר אדם בית]\u0006 — \u0003לכולהו\u0004 \u0005[לכל]\u0006 \u0003ימות הגשמים אגר\u0004 \u0005[הוא שוכר]\u0006 ולכן כל השוכר בסוף הקיץ דעתו לכל החורף עד ניסן כאשר מסתיימת תקופת הגשמים.","ושואלים: \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של ה\u0003ברייתא ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 של המשנה, הסוברים שאין למנות ראש השנה לשכירות בתים באחד בניסן מה טעמם? ומסבירים: לדעתם \u0003בניסן נמי מישכח שכיח קיטרי\u0004 \u0005[גם כן שכיח,\u0006 מצוי \u0005שיתקשרו\u0006 עבים ויירד מטר\u0005]\u0006 ולכן אין לקבוע בהחלטיות שאדם שוכר דירה רק עד ניסן, אלא מן הסתם רצונו להמשיך את חוזה השכירות עד לאחר ניסן כדי שלא יהא מצב שלא יהא לו בית בזמן הגשמים.","עתה חוזרים לפירוש המשנה. נאמר בה כי \u0003באחד באלול ראש השנה למעשר בהמה.\u0004 ומעירים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 משנתנו — כשיטת \u0003ר' מאיר היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' מאיר אומר, באחד באלול ראש השנה למעשר בהמה.\u0004","ושואלים: הלא לפי האמור קודם שאחד בניסן הוא ראש השנה \u0003לרגלים, מני\u0004 \u0005[ל\u0006שיטת \u0005מי היא]\u0006 המשנה — כשיטת \u0003ר' שמעון היא,\u0004 שלשיטתו אין עובר על \"בל תאחר\" אלא אם כן עברו שלוש רגלים כסידרם וכפי שהעמידו את שיטת המשנה כדבריו (לעיל ראש השנה ד, א). \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של משנתנו\u0005],\u0006 \u0003ר' אלעזר ור' שמעון אומרים: באחד בתשרי\u0004 ראש השנה למעשר בהמה. ואם נצרף את הדברים נמצא כי \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 כשיטת \u0003ר' שמעון, ומציעתא\u0004 \u0005[ואמצע\u0006 המשנה\u0005]\u0006 ביחס למעשר בהמה הוא כשיטת \u0003ר' מאיר,\u0004 ותמוה שתהא משנה כגון זו.","\u0003אמר רב יוסף:\u0004 כל המשנה כולה שיטת \u0003רבי היא, ונסיב לה אליבא דתנאי\u0004 \u0005[ולוקח,\u0006 מביא, \u0005אותה\u0006 בצירוף שיטותיהם \u0005של תנאים\u0006 שונים\u0005]\u0006 שדעתו לפסוק כמותם להלכה בנושאים שונים. \u0003ברגלים סבר לה\u0004 \u0005[סובר]\u0006 רבי \u0003כ\u0004שיטת \u0003ר' שמעון ובמעשר בהמה סבר לה כ\u0004שיטת \u0003ר' מאיר.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 כיצד הם \u0003ארבעה\u0004 ראשי שנה? שאם אנו אומרים שהתנא של משנתנו סבור שאחד באלול הוא ראש שנה, אם כן \u0003חמשה\u0004 ראשי שנים \u0003הוו\u0004 \u0005[הם]\u0006 (אחד בניסן, חמישה עשר בניסן, אחד באלול, אחד בתשרי וחמישה עשר בשבט)! \u0003אמר רבא: ארבעה\u0004 הם \u0003לדברי הכל;\u0004 כי \u0003ל\u0004שיטת \u0003ר' מאיר\u0004 הם \u0003ארבעה,\u0004 כי \u0003דל\u0004 \u0005[הוצא]\u0006 מכאן את ראש השנה ל\u0003רגלים,\u0004 שהרי לדעתו אין זמן קבוע למנין תחילת הרגלים. ואף לדעת \u0003ר' שמעון\u0004 יש \u0003ארבעה\u0004 ראשי שנים — \u0003דל\u0004 \u0005[הוצא]\u0006 \u0003מעשר בהמה,\u0004 שלדעתו הוא באחד בתשרי.","\u0003רב נחמן בר יצחק אמר:\u0004 כך יש להבין — \u0003ארבעה חדשים\u0004 הם שיש \u0003בהן כמה ראשי שנים,\u0004 שבניסן יש לדעת רבי מאיר ראש שנה הן למלכים והן לרגלים, אף שאינם חלים באותו יום.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא, שבה שנינו: \u0003ששה עשר בניסן\u0004 הוא \u0003ראש השנה\u0004 לענין \u0003העומר,\u0004 שהרי מתאריך זה ואילך מותר לאכול מן התבואה החדשה. \u0003ששה בסיון\u0004 — \u0003ראש השנה לשתי הלחם\u0004 שמיום זה מביאים למקדש מנחות מן התבואה החדשה. ואם כן, לשיטת \u0003רבא ליתני\u0004 \u0005[שישנה]\u0006 במשנתנו: \u0003ששה\u0004 ראשי שנה הם (גם שישה עשר בניסן ושישה בסיון) ולדעת \u0003רב נחמן בר יצחק ליתני\u0004 \u0005[שישנה]\u0006 לפחות \u0003חמשה,\u0004 שהרי סיון אף הוא חודש שיש בו ראש השנה,","\u0003אמר רב פפא: כי קא חשיב\u0004 \u0005[כאשר מונה הוא]\u0006 במשנה הריהו מונה \u0003מידי דחייל מאורתא\u0004 \u0005[הדברים שמתחילים מן הערב]\u0006 מתחילתו של היום. אולם \u0003מידי\u0004 \u0005[דבר]\u0006 \u0003דלא חייל מאורתא לא קא חשיב\u0004 \u0005[דבר שאינו חל מן הערב אין הוא מונה]\u0006 וכיון שהתאריכים הנקבעים על ידי העומר ושתי הלחם אינם חלים מן הערב אלא משעת הקרבתם — אינו מונה אותם.","ומקשים: \u0003והרי רגלים, דלא חיילי מאורתא\u0004 \u0005[שאינם חלים מן הערב],\u0006 שאין איסור \"בל תאחר\" חל עם התחלת הרגל בערב אלא בבוקר לאחר הקרבת התמיד בזמן הראוי להקרבת שאר הקרבנות ובכל זאת \u0003קחשיב\u0004 \u0005[מונה\u0006 אותם\u0005]!\u0006 ומשיבים: \u0003כיון שצריך לאיתויי מעיקרא\u0004 \u0005[להביא מתחילה]\u0006 וחיוב הפרשת הקרבן חל מיד מן הערב אם כן הרי \u0003מיחייב וקאי\u0004 \u0005[הוא חייב ועומד\u0006 כבר מתחילתו\u0005].\u0006","ומקשים: \u0003והרי יובלות, דלא חיילי מאורתא\u0004 \u0005[שאינם חלים מן הערב],\u0006 אלא משעת תקיעת שופר ביום, \u0003ו\u0004בכל זאת \u0003קחשיב\u0004 \u0005[מונה אותם]!\u0006 ומשיבים: משנתנו כשיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא היא,\u0004 ש\u0003אמר: מראש השנה\u0004 מיד \u0003חייל\u0004 \u0005[חל]\u0006 ה\u0003יובל\u0004 ואין תקיעת השופר אלא לגמר השחרור, ולכן ראוי למנותו.","\u0003רב שישא בריה דרב אידי אמר\u0004 הסבר אחר מדוע לא נמנו במשנה עומר ושתי הלחם: \u0003כי קא חשיב\u0004 \u0005[כאשר מנה\u0006 במשנתנו\u0005]\u0006 מנה \u0003מידי דלא תלי\u0004 \u0005[דבר שאינו תלוי]\u0006 \u0003במעשה,\u0004 כגון הקרבת העומר, אולם \u0003מידי דתלי\u0004 \u0005[דבר התלוי]\u0006 \u0003במעשה לא קא חשיב\u0004 \u0005[מנה].\u0006","ומקשים: \u0003והרי רגלים,\u0004 הם \u0003מידי דתלי\u0004 \u0005[דבר התלוי]\u0006 \u0003במעשה,\u0004 בהקרבת התמיד \u0003וקא חשיב\u0004 \u0005[ו\u0006בכל זאת \u0005מונה אותם]!\u0006 ומשיבים: אין כן הדבר, אלא \u0003\"בל תאחר\" ממילא חייל\u0004 \u0005[מעצמו הוא חל]\u0006 מתחילת היום אם לא הביא את הקרבן בזמנו ואין הדבר תלוי בשעת הקרבת הקרבנות."],["ומקשים: \u0003והרי יובלות\u0004 שהם תלויים במעשה של תקיעה ומונה אותם! ומשיבים: כשיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקא היא,\u0004 שלדעתו אף היובל אינו תלוי בכך.","\u0003ורב אשי אמר\u0004 הסבר אחר: אכן ישנם יותר מארבע ראשי שנים, ואלה שמנאם דבר מיוחד יש בהם. וכך אמר: \u0003ארבע ראשי השנים הם שהן\u0004 חלים \u0003בארבע ראשי חדשים\u0004 ואילו שאר ראשי שנים אינם חלים בראש חודש.","ומקשים: \u0003באחד בשבט\u0004 הרי הוא ראש השנה רק לדעת \u0003בית שמאי,\u0004 ואם כן לשיטות אחרות אינם אפילו ארבעה\u0003!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003שלשה\u0004 (ראשי שנים הם החלים בראש חודש) \u0003לדברי הכל,\u0004 ואילו \u0003באחד בשבט\u0004 — \u0003מחלוקת בית שמאי ובית הלל.\u0004","במשנתנו שנינו ש\u0003ר' אלעזר ור' שמעון אומרים\u0004 שראש השנה למעשר בהמה הוא \u0003באחד בתשרי. אמר ר' יוחנן: ושניהם\u0004 רבי מאיר ורבי אלעזר \u0003מקרא אחד דרשו\u0004 בדרכים שונות, \u0003שנאמר: \"לבשו כרים הצאן ועמקים יעטפו בר יתרועעו אף ישירו\"\u0004 (תהלים סה, יד). \u0003ר' מאיר סבר: אימתי לבשו כרים הצאן\u0004 מתי זמן הרביעה של הצאן — \u0003בזמן שעמקים יעטפו בר,\u0004 כלומר, כשהעמקים מתכסים בתבואה. \u0003ואימתי עמקים יעטפו בר\u0004 — \u0003באדר,\u0004 אם כן \u0003מתעברות\u0004 הצאן באדר \u0003ויולדות\u0004 שישה חדשים אחר כך \u0003באב,\u0004 ואם כן \u0003ראש השנה שלהן\u0004 ראוי שיהא בראש חודש \u0003אלול\u0004 שעד אז נולדו רוב בני הצאן בשנה זו.","ואילו \u0003ר' אלעזר ור' שמעון אומרים: אימתי לבשו כרים הצאן,\u0004 מתי הוא זמן הרביעה הרגיל — \u0003בזמן ש\"יתרועעו אף ישירו\", אימתי שבלים אומרות שירה,\u0004 כלומר, מתי הן מליאות והן משיקות זו עם זו ברוח ומשמיעות רחש־שירה — \u0003בניסן,\u0004 ולשיטה זו \u0003מתעברות\u0004 הרחלים \u0003בניסן ויולדות באלול\u0004 אם כן ראוי שיהא \u0003ראש השנה שלהן\u0004 באחד ב\u0003תשרי.\u0004","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"יתרועעו אף ישירו\"!\u0004 ומשיבים: \u0003ההוא\u0004 מדבר \u0003באפלתא\u0004 \u0005[ב\u0006רחלים \u0005אפילות,\u0006 מאחרות\u0005],\u0006 שמתעברות לאחר זמנן \u0003דהויין\u0004 \u0005[שהן\u0006 מתעברות\u0005]\u0006 \u0003בניסן.\u0004 ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחרים גם כן]\u0006 רבי אלעזר ורבי שמעון \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ועמקים יעטפו בר\"\u0004 שהוא באדר! ומשיבים: \u0003ההוא\u0004 מדבר \u0003בחרפייתא דאתיין\u0004 \u0005[במקדימות הבאות]\u0006 \u0003מאדר.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 פירושו של הפסוק הוא \u0003כדכתיב\u0004 \u0005[כפי שנאמר]\u0006 לפי הסדר במקרא \u0003\"לבשו כרים הצאן\"\u0004 — \u0003בזמן ש\"עמקים יעטפו בר\", ואיכא נמי\u0004 \u0005[ויש גם כן]\u0006 מקרים שבהם מתאחר הדבר עד לזמן ש\u0003\"יתרועעו אף ישירו\". אלא ל\u0004דעת \u0003ר' אלעזר ור' שמעון איפכא מיבעי ליה\u0004 \u0005[להיפך היה צריך שיהיה\u0006 כתוב\u0005]:\u0006 \u0003\"לבשו כרים הצאן\"\u0004 — \u0003בזמן ש\"יתרועעו אף ישירו\" ואיכא נמי\u0004 \u0005[ויש גם כן]\u0006 מקרים שמקדימים בזמן \u0003ש\"עמקים יעטפו בר\".\u0004 ואם כן, לדעתם אין המקראות כתובים כסידרם!","\u0003אלא אמר רבא,\u0004 כך צריך לפרש את המחלוקת: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003\"לבשו כרים הצאן\"\u0004 הוא בעיקר \u0003בזמן ש\"עמקים יעטפו בר\",\u0004 כלומר, בחודש \u0003אדר,\u0004 ולא בנושא זה נחלקו. אלא \u0003הכא בהאי קרא קמיפלגי\u0004 \u0005[כאן בכתוב זה נחלקו];\u0006 נאמר: \u0003\"עשר תעשר\u0004 את כל תבואת זרעך היוצא השדה שנה שנה. ואכלת לפני ה' אלוקיך במקום אשר יבחר לשכן שמו שם מעשר דגנך תירושך ויצהרך ובכורות בקרך וצאנך למען תלמד ליראה את ה' אלוקיך כל הימים \"(דברים יד, כב-כג) \u0003בשני מעשרות הכתוב מדבר, אחד מעשר בהמה ואחד מעשר דגן.\u0004","ובכך היא המחלוקת: \u0003ר' מאיר סבר, מקיש\u0004 \u0005[משווה]\u0006 הכתוב \u0003מעשר בהמה למעשר דגן\u0004 באופן זה: \u0003מה מעשר דגן\u0004 — \u0003סמוך לגמרו\u0004 של היבול לאחר סוף ייבושו בשדה הוא זמן \u0003עישורו,\u0004 בתשרי, \u0003אף מעשר בהמה סמוך לגמרו עישורו,\u0004 וגמרו הוא בסוף חודש אב, ולכן זמנו לענין מעשר בראש חודש אלול. ואילו \u0003ר' אלעזר ור' שמעון סברי\u0004 \u0005[סבורים]\u0006 כי \u0003מקיש\u0004 \u0005[משווה]\u0006 הכתוב \u0003מעשר בהמה למעשר דגן\u0004 לענין התאריך, \u0003מה מעשר דגן ראש השנה שלו תשרי\u0004 — \u0003אף מעשר בהמה ראש השנה שלו תשרי.\u0004","שנינו במשנה כי \u0003באחד בתשרי\u0004 הוא \u0003ראש השנה לשנים.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה, לאיזו הלכה]\u0006 נאמר הדבר? \u0003אמר רב פפא: לשטרות. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שטרי חוב המוקדמין,\u0004 שהתאריך שנכתב בהם מוקדם למעשה שכתוב בהם — הרי הם \u0003פסולין, והמאוחרין,\u0004 שהתאריך שנכתב בהם מאוחר מזמן המעשה — \u0003כשירין.\u0004 ומאחר והזמן המופיע בשטר עשוי לקבוע את כשרותו, לכן יש לדעת מה הוא התאריך בו מתחילה כל שנה.","ותוהים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 כבר במשנתנו\u0005]:\u0006 \u0003באחד בניסן ראש השנה למלכים, ואמרינן\u0004 \u0005[ואמרנו]\u0006 בענין זה: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמר הדבר — \u0003ואמר רב חסדא\u0004 שהכוונה היא \u0003לשטרות.\u0004 ואם הזמן לשטרות הוא בניסן הרי אין ענין לשטרות בתשרי!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כאן\u0004 שהתאריך בשטרות נקבע \u0003ל\u0004פי מנין שנות שלטון \u0003מלכי ישראל\u0004 — מונים מניסן, \u0003כאן\u0004 שמונים \u0003למלכי אומות העולם\u0004 — מונים מתשרי.","ושואלים: \u0003אלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב חסדא\u0004 בפירוש משנתנו כי \u0003לא שנו אלא למלכי ישראל אבל למלכי אומות העולם מתשרי מנינן\u0004 \u0005[מונים אנו],\u0006 וכי \u0003רב חסדא מתניתין אתא לאשמועינן\u0004 \u0005[משנתנו בא להשמיענו]\u0006 והרי לפי מה שהסברנו נאמר כבר הדבר במשנה?!","ומשיבים: \u0003לא, רב חסדא קראי אתא לאשמועינן\u0004 \u0005[\u0006את פירוש \u0005הכתובים בא להשמיענו]\u0006 ולא כפי שהוסברו הדברים בראש פרק זה בישוב התאריכים השונים בענייני המלכים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003רב חסדא כ\u0004שיטת \u0003ר' זירא מתני לה\u0004 \u0005[שונה הוא אותה]\u0006 ולדעתו ראש השנה לשנים שנאמר במשנה לא לענין שטרות נאמר, אלא לענין אחר. ש\u0003ר' זירא אמר: לתקופה,\u0004 שאחד בתשרי הוא יום ראשון לחשבונות השנים וחשבונות תקופות החמה ומולדות הלבנה, שכולם נמנים מתשרי, וכשיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: ב\u0004חודש \u0003תשרי נברא העולם.\u0004 וכל החשבונות בנויים לפי תאריך יסודי זה.","\u0003רב נחמן בר יצחק אמר:\u0004 מה שאמרנו שבאחד בתשרי הוא ראש השנה לשנים הוא \u0003ל\u0004ענין \u0003דין,\u0004 שביום זה נידון העולם עבור השנה כולה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ארץ אשר ה' אלוהיך דורש אותה תמיד עיני ה' אלהיך בה \u0003מראשית השנה ועד אחרית שנה\"\u0004 (דברים יא, יב), לומר ש\u0003מראשית השנה נידון מה יהא בסופה.\u0004","ושואלים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 יודעים אנו שב\u0003תשרי הוא\u0004 יום הדין? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תקעו בחדש שופר בכסה ליום חגנו\"\u0004 (תהלים פא, ד), ונברר \u0003איזהו חג\u0004"],["\u0003שהחדש,\u0004 כלומר, הירח \u0003מתכסה בו\u0004 — \u0003הוי אומר זה ראש השנה,\u0004 כי זה הוא החג היחיד החל בראשית החודש, כאשר עדיין אין הירח נראה בו. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בסמוך לו: \u0003\"כי חק לישראל הוא משפט לאלהי יעקב\"\u0004 (תהלים פא, ה), משמע שיום זה הוא יום המשפט.","על אותו כתוב \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"כי חק לישראל הוא משפט לאלהי יעקב\"\u0004 — \u0003מלמד שאין בית דין של מעלה נכנסין לדין אלא אם כן קידשו בית דין של מטה את החדש,\u0004 שלאחר שישראל קובעים את היום הזה כחוק — אז נעשה המשפט בבית דין של מעלה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 נאמר: \u0003\"כי חק לישראל הוא\", אין לי אלא\u0004 שהוא יום דין \u0003לישראל,\u0004 שהוא יום דין אף \u0003לאומות העולם מנין — תלמוד לומר: \"משפט לאלהי יעקב\"\u0004 שהוא המושל בכל העולם כולו. \u0003אם כן,\u0004 אם הוא חוק לכל באי עולם, \u0003מה תלמוד לומר \"כי חק לישראל\",\u0004 אלא \u0003מלמד שישראל נכנסין תחילה לדין.\u0004","ו\u0003כ\u0004דברי \u0003רב חסדא\u0004 בנושא אחר, ש\u0003אמר רב חסדא: מלך וצבור\u0004 הבאים לדין לפני ה' — \u0003מלך נכנס תחילה לדין, שנאמר:\u0004 \"ויהיו דברי אלה אשר התחננתי לפני ה' קרובים אל ה' אלוקינו יומם ולילה לעשות \u0003משפט עבדו ומשפט עמו\u0004 ישראל דבר יום ביומו\" (מלכים א' ח, נט).","ושואלים: \u0003ובאמת מאי טעמא\u0004 \u0005[מה טעם]\u0006 מקדימים את המלך? ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לאו אורח ארעא למיקם מלכא אבראי\u0004 \u0005[אין זה דרך ארץ שיעמוד המלך בחוץ]\u0006 וימתין עד סיום משפטם של נתיניו, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003מקמי דליפוש\u0004 \u0005[מלפני שירבה]\u0006 \u0003חרון אף\u0004 על רשעי ישראל, ומשום חרון אף זה יענש גם המלך, ומשום כך אמרו שיכנס המלך תחילה ועל ידי כך יוכל להנצל מדין קשה.","שנינו במשנה כי אחד בתשרי הוא ראש השנה \u0003לשמיטין.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שכן הוא? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובשנה השביעת שבת שבתון יהיה לארץ\"\u0004 (ויקרא כה, ד) \u0003וגמר\u0004 \u0005[ולמד]\u0006 בגזירה שווה מן המילים \u0003\"שנה\" \"שנה\" מתשרי,\u0004 שנאמר: \u0003\"מראשית השנה\"\u0004 (דברים יא, יב) ושם מדובר בשנה המתחילה עם תקופת הגשמים.","ומקשים: \u0003ולגמור\u0004 \u0005[ושילמד]\u0006 \u0003\"שנה\" \"שנה\"\u0004 בגזירה שווה \u0003מניסן, דכתיב\u0004 \u0005[ש\u0006אף בו \u0005נאמר]\u0006 \u0003\"ראשון הוא לכם לחדשי השנה\"\u0004 (שמות יב, ב)! ומשיבים: \u0003דנין שנה שאין עמה חדשים משנה שאין עמה חדשים\u0004 הכתובה בחודש תשרי, \u0003ואין דנין שנה שאין עמה חדשים\u0004 שבשמיטה \u0003משנה שיש עמה חדשים,\u0004 לפי שבאותו כתוב הכוונה היא בעיקר לסדר החודשים בתוך השנה.","עוד שנינו במשנה כי אחד בתשרי הוא ראש השנה \u0003ליובלות.\u0004 ושואלים: \u0003וכי יובלות באחד בתשרי הוא\u0004 תחילתם? הלא ראש השנה ל\u0003יובלות בעשרה בתשרי הוא! דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בחודש השביעי בעשור לחודש ביום הכפרים תעבירו שופר\u0004 בכל ארצכם. וקדשתם את שנת החמישים שנה וקראתם דרור בארץ לכל יושביה יובל היא תהיה לכם\"\u0003 (ויקרא כה, ט-י). \u0004","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003:\u0004 זה שנאמר לגבי היובל \u0003\"וקדשתם את שנת החמשים שנה\" (ויקרא כה, ט—י), מה תלמוד לומר? לפי שנאמר\u0004 שתהא תקיעת השופר של יובל \u0003ביום הכפרים, יכול לא תהא מתקדשת\u0004 שנת היובל \u0003אלא מיום הכפרים ואילך\u0004 — \u0003תלמוד לומר: \"וקדשתם את שנת החמשים\"\u0004 — \u0003מלמד שמתקדשת והולכת מתחילתה\u0004 מהיום שבו מתחילה השנה.","\u0003מכאן אמר ר' ישמעאל בנו של ר' יוחנן בן ברוקא\u0004 ששני הכתובים מתיישבים באופן זה: \u0003שמראש השנה עד יום הכפורים\u0004 של שנת יובל \u0003לא היו עבדים נפטרין לבתיהן\u0004 — שהרי עדיין לא נשמעה תקיעת שופר, \u0003ולא\u0004 היו \u0003משתעבדין לאדוניהם\u0004 — שהרי כבר התחילה שנת היובל \u0003אלא אוכלין ושותין ושמחין, ו\u0004אם רוצים, אף יניחו \u0003עטרותיהן בראשיהן\u0004 כבני חורין. \u0003כיון שהגיע יום הכפורים תקעו בית דין בשופר, נפטרו עבדים לבתיהן ושדות\u0004 שנמכרו \u0003חוזרות לבעליהן.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 כיצד מפרשים הם את הכתוב \"וקדשתם את שנת החמישים שנה\"? ומשיבים: הם למדים מכאן ש\u0003שנים אתה מקדש ואי\u0004 (אין) \u0003אתה מקדש חדשים.\u0004 כאותה שיטה שאין בית דין מצווים לקבוע ולקדש את החודש כלל, אבל הם מצווים לקדש את שנת החמישים, שעליהם לומר: \"מקודשת השנה\".","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 זה שנאמר \u0003\"יובל היא\"\u0004 (ויקרא כה, ט—י), \u0003מה תלמוד לומר? לפי שנאמר: \"וקדשתם את שנת החמשים\", יכול כשם שמתקדשת והולכת מתחילתה כך מתקדשת והולכת בסופה,\u0004 שעד יום הכיפורים של שנת החמישים ואחת תשאר קדושת שנת היובל, \u0003ואל תתמה\u0004 שכן הוא, \u0003שהרי מוסיפין מחול על קדש\u0004 בכמה זמנים בין בכניסתו בין ביציאתו של זמן בקודש — \u0003תלמוד לומר: \"יובל היא שנת החמשים\"\u0004 (ויקרא כה, ט—י) ללמדנו: \u0003שנת החמשים אתה מקדש, ואי אתה מקדש\u0004 את \u0003שנת החמשים ואחת\u0004 ואפילו בחלקה\u0003.\u0004"],["ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם סבורים ששנת היובל מתקדשת מתחילתה ולכן אינם צריכים ללמוד מ\"היא\" לסופה, כיצד מבינים הם כתוב זה? הם מפרשים: \u0003שנת חמשים אתה מונה, ואי אתה מונה שנת חמשים ואחת.\u0004 ומה בא דבר זה ללמדנו — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה,\u0004 ש\u0003אמר: שנת חמשים עולה לכאן ולכאן,\u0004 שלשיטתו שנת היובל נמנית גם כשנה ראשונה של השמיטה הבאה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בברייתא זו \u0003שלא\u0004 כדבריו, שחכמים אומרים ששנת היובל היא סיום של מחזור אחד, והשנה שלאחר היובל היא תחילת מנין חדש של השמיטות.","אגב מה שנאמר קודם שואלים: \u0003וכלל זה שמוסיפין מחול על קדש מנלן\u0004 \u0005[מניין לנו]?\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003:\u0004 נאמר \u0003\"בחריש ובקציר תשבת\"\u0004 (שמות לד, כא), \u0003ר' עקיבא אומר: אינו צריך לומר\u0004 וללמד על \u0003חריש וקציר של שביעית\u0004 עצמה, \u0003שהרי כבר נאמר\u0004 \"ובשנה השביעית שבת שבתון יהיה לארץ שבת לה' \u0003שדך לא תזרע\" (ויקרא כה, ד), אלא\u0004 \"בחריש ובקציר תשבות\" בא ללמדנו על \u0003חריש של ערב שביעית הנכנס\u0004 ומועיל \u0003ל\u0004צמיחה של ה\u0003שביעית, וקציר של שביעית\u0004 שגדל באותה שנה, \u0003היוצא למוצאי שביעית\u0004 שאף בו נוהגים קדושת שביעית, הרי שמוסיפים על קדושת שנת השמיטה מלפניה ומלאחריה.","\u0003ר' ישמעאל אומר:\u0004 הכתוב \"בחריש ובקציר תשבות\" משמעו: \u0003מה חריש\u0004 שהוא תמיד \u0003רשות,\u0004 שאין חריש של מצוה — \u0003אף קציר\u0004 שנאסר בשמיטה הוא דווקא קציר של \u0003רשות, יצא קציר העומר שהוא\u0004 קציר \u0003מצוה,\u0004 ואינו נכלל באיסור התורה ומותר איפוא לקצור את העומר אף בשנת השמיטה.","ושואלים: \u0003אם כן, ור' ישמעאל\u0004 כלל זה \u0003שמוסיפין מחול על קדש מנא ליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד לו\u0005]\u0006 כלל זה \u0003מדתניא\u0004 \u0005[ממה ששנויה\u0006 ברייתא\u0005],\u0006 נאמר בענין יום הכיפורים: \u0003\"ועניתם את נפשתיכם בתשעה\u0004 לחודש בערב \u0003\"(ויקרא כג, לב), יכול בתשעה\u0004 ממש יתחיל להתענות? \u0003תלמוד לומר: \"בערב\", אי\u0004 \u0005[אם]\u0006 \u0003בערב יכול משתחשך,\u0004 כלומר, ממש רק מן הלילה, שהוא מתחילת היום העשירי? \u0003תלמוד לומר: \"בתשעה\" הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מתיישבים הכתובים? \u0003מתחיל ומתענה\u0004 זמן קצר \u0003מבעוד יום\u0004 בסופו של תשיעי — \u0003מלמד\u0004 כתוב זה \u0003שמוסיפין מחול על קדש.\u0004","\u0003אין לי אלא\u0004 שעושים תוספת כזו \u0003בכניסתו\u0004 של יום הכיפורים, \u0003ביציאתו מנין\u0004 שמוסיפים? \u0003תלמוד לומר: \"מערב עד ערב\u0004 תשבתו שבתכם\" (ויקרא כג, לב) ללמדנו שכשם שמוסיפים בכניסה — כך מוסיפים ביציאה.","\u0003אין לי אלא יום הכפורים,\u0004 שמפורשת בו תוספת זו, \u0003שבתות מנין\u0004 שאף בהן מוסיפים — \u0003תלמוד לומר: \"תשבתו\"\u0004 ימי שבת אחרים. \u0003ימים טובים מנין\u0004 שאף הם בכלל הוספה? \u0003תלמוד לומר: \"שבתכם\"\u0004 ללמד: כל יום שיש בו מצות שביתה יש להוסיף על הקודש. \u0003הא כיצד? כל מקום שיש בו\u0004 מצות \u0003שבות\u0004 — \u0003מוסיפין מחול על קדש.\u0004","ושואלים: \u0003ור' עקיבא, האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"ועניתם את נפשתיכם בתשעה\" מאי עביד ליה\u0004 \u0005[מה עושה הוא בו],\u0006 שהרי את ההלכה על תוספת לקודש לומד הוא ממקור אחר! ומשיבים: \u0003מבעי ליה\u0004 \u0005[צריך הוא אותו]\u0006 \u0003לכדתני\u0004 \u0005[לכפי ששנה]\u0006 \u0003חייא בר רב מדפתי\u0004 שהביא ברייתא זו. \u0003דתני חייא בר רב מדפתי\u0004, נאמר: \u0003\"ועניתם את נפשותיכם בתשעה\" וכי בתשעה מתענין? והלא בעשירי מתענין! אלא לומר לך: כל האוכל ושותה בתשיעי\u0004 כראוי \u0003מעלה עליו\u0004 (מחשיב לו) \u0003הכתוב\u0004 את האכילה הזו, שהיא הכנה לצום,"],["\u0003כאלו התענה\u0004 גם \u0003תשיעי ו\u0004גם \u0003עשירי.\u0004","אגב הזכרת ראש שנת היובל מביאים דברים נוספים שנאמרו בנושא זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב \"וקדשתם את שנת החמישים שנה וקראתם דרור בארץ לכל יושביה \u0003יובל היא\u0004 תהיה לכם\" (ויקרא כה, י): ההדגשה \"יובל הוא\" באה ללמד \u0003אף על פי שלא שמטו\u0004 את הכספים ואת הקרקעות, \u0003אף על פי שלא תקעו\u0004 בשופר הרי היא בכל זאת יובל. \u0003יכול אף על פי שלא שלחו\u0004 את העבדים עדיין תיחשב זו שנת יובל — \u0003תלמוד לומר \"היא\"\u0004 — למעט. כלומר יש לשמור בכל זאת משהו מעיקרי דיני השנה, ואם לא אין זה יובל, אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' יוסי אומר: \"יובל היא\"\u0004 — \u0003אף על פי שלא שמטו, אף על פי שלא שלחו. יכול אף על פי שלא תקעו\u0004 אף אז תהא זו שנת יובל — \u0003תלמוד לומר: \"היא\"\u0004 — למעט.","ורבי יוסי מסביר את שיטתו: \u0003וכי מאחר שמקרא אחד מרבה\u0004 שבכל אופן הוא יובל, \u0003ומקרא אחד ממעיט, מפני מה אני אומר\u0004 ש\u0003\"יובל היא\"\u0004 בא ללמד כי הוא יובל \u0003אף על פי שלא שלחו ואין\u0004 הוא \u0003יובל אלא אם כן תקעו? לפי שאפשר לעולם בלא שילוח עבדים,\u0004 שהרי יתכן שלא יהיו עבדים עבריים משועבדים כלל באותה שנה, \u0003ואי אפשר לעולם בלא תקיעת שופר.\u0004 כלומר, דבר זה הלא אפשר לעשותו תמיד, ועל כן ודאי שעל כך הקפיד הכתוב.","\u0003דבר אחר: זו\u0004 תקיעת השופר \u0003מסורה לבית דין,\u0004 שעליהם החובה לתקוע. \u0003וזו\u0004 שילוח עבדים \u0003אינה מסורה לבית דין\u0004 אלא לכל אדם, ואין לתלות הלכה קבועה אלא בדברים שהם בידי בית דין ולא במעשי היחידים.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003דבר אחר.\u0004 כלומר, מה טעם הוצרך רבי יוסי להוסיף עוד נימוק לדבריו? כך יש לומר: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003אי אפשר\u0004 לא יתכן \u0003דליכא חד\u0004 \u0005[שאין\u0006 אדון \u0005אחד]\u0006 אי־שם \u0003בסוף העולם דלא משלח\u0004 \u0005[שאינו משלח]\u0006 את עבדו, מכל מקום אפשר לומר: \u0003זו\u0004 התקיעה — \u0003מסורה לבית דין, וזו\u0004 שחרור העבדים — \u0003אינה מסורה לבית דין.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי כדקאמר טעמיה\u0004 \u0005[שאמר\u0006 ופירש \u0005את טעמו],\u0006 \u0003אלא לר' יהודה מאי טעמא\u0004 \u0005[מה טעם]\u0006 תולה הוא את שנת היובל בשילוח עבדים? ומסבירים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וקראתם דרור בארץ\"\u0004 (ויקרא כה, י), ומיד לאחר מכן נאמר \"יובל היא\", \u0003וקסבר\u0004 \u0005[וסבור]\u0006 רבי יהודה: \u0003מקרא נדרש לפניו,\u0004 לפסוק הקודם, שהמיעוט של \"יובל היא\" מתקשר לכתוב באותו פסוק \u0003לפניו\u0004 (\"וקראתם דרור בארץ\") \u0003ולא\u0004 לש \u0003לפני פניו,\u0004 לפסוק המדבר בתקיעת שופר (\"והעברת שופר תרועה בחודש השביעי בעשור לחודש ביום הכיפורים תעבירו שופר בכל ארצכם\". ויקרא כה, ט).","ושואלים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 ברור כי \u0003'דרור'\u0004 הוא \u0003לשון חירות, מאי משמע\u0004 \u0005[מה המשמעות,\u0006 מהיכן מובן הדבר\u0005]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין 'דרור' אלא לשון חירות. אמר ר' יהודה: מה לשון 'דרור'\u0004 — \u0003כמדייר בי דיירא\u0004 \u0005[כפי\u0006 שאדם \u0005שדר בכל דירה]\u0006 \u0003ומוביל סחורה בכל מדינה,\u0004 ולכן הוא נקרא 'דרור' — אדם שיכול לדור בכל מקום.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: זו דברי ר' יהודה ור' יוסי, אבל חכמים אומרים: שלשתן מעכבות בו\u0004 ביובל: שמיטת קרקעות, תקיעת שופר ושילוח עבדים. \u0003קסברי\u0004 \u0005[סבורים הם]:\u0006 \u0003מקרא נדרש לפניו, ולפני פניו, ולאחריו\u0004 שכל הדינים הללו נאמרו בפרשה זו ולגבי כולם נאמר \"יובל היא\".","ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"יובל\"\u0004 שבא לרבות שיהא יובל מכל מקום! ומשיבים: \"יובל\" \u0003ההוא\u0004 בא ללמד ש\u0003אפילו בחוצה לארץ\u0004 נוהגת מצות היובל. ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"בארץ\"\u0004 (ויקרא כה, י)! ומשיבים: \"בארץ\" בא ללמדנו: \u0003בזמן שנוהג דרור בארץ\u0004 — \u0003נוהג\u0004 אף \u0003בחוצה לארץ, בזמן שאינו נוהג בארץ\u0004 — \u0003אינו נוהג בחוצה לארץ\u0004 כלל.","עוד שנינו במשנה, כי אחד בתשרי הוא ראש השנה \u0003לנטיעה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שלש שנים\u0004 יהיה לכם \u0003ערלים\u0004 לא יאכל\u0003\"\u0004 (ויקרא יט, כג) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ובשנה הרביעית\u0004 יהיה כל פריו קודש הלולים לה'\u0003\"\u0004 (ויקרא יט, כד) \u0003ויליף\u0004 \u0005[ולומד]\u0006 בגזירה שווה \u0003\"שנה\" \"שנה\" מ\u0004חודש \u0003תשרי דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]\u0006 \u0003\"מראשית השנה\"\u0004 (דברים יא, יב), ומקשים:","\u0003וליגמר\u0004 \u0005[ושילמד]\u0006 \u0003שנה שנה מניסן, דכתיב\u0004 \u0005[שנאמר\u0006 \u0003בו\u0004\u0005]:\u0006 \u0003\"ראשון הוא לכם לחדשי השנה\"\u0004 (שמות יב, ב)?! ודוחים: \u0003דנין שנה שאין עמה חדשים\u0004 הכתובה בערלה \u0003משנה שאין עמה חדשים\u0004 הכתובה בתשרי, \u0003ואין דנין שנה שאין עמה חדשים משנה שיש עמה חדשים\u0004 כגון זו הכתובה בניסן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד הנוטע ואחד המבריך,\u0004 כלומר, שכופף ענפי אילן (כגון גפן) ושותל אותם באדמה כדי שישתרשו שם, \u0003ואחד המרכיב\u0004 ענף בתוך אילן, אם עשה זאת ב\u0003ערב\u0004 שנת ה\u0003שביעית שלשים יום לפני ראש השנה\u0004 — \u0003עלתה לו שנה\u0004 כלומר נחשב לו זמן זה כשנה שלימה לענין מנין שנות הערלה \u0003ו\u0004הפירות שצמחו — \u0003מותר לקיימן בשביעית,\u0004 שאין זה נחשב כדבר שנעשה בשנה השביעית. אולם אם נעשה הדבר \u0003פחות משלשים יום לפני ראש השנה\u0004 — \u0003לא עלתה לו שנה\u0004 לענין ערלה, \u0003ו\u0004הפירות שצמחו בו \u0003אסור לקיימן בשביעית\u0004"],["ומעירים: \u0003ופירות נטיעה זו,\u0004 אף שנגמרו שלוש שנים בתשרי, מכל מקום \u0003אסורין\u0004 הם באכילה \u0003עד חמישה עשר בשבט\u0004 באותה שנה, \u0003אם\u0004 לענין \u0003ערלה\u0004 שבשלוש השנים הראשונות הרי הם אסורים משום \u0003ערלה, ואם\u0004 לענין נטע \u0003רבעי\u0004 שיש לפדות פירות אלה שבשנה הרביעית הרי הם \u0003רבעי.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שאף שנסתיימו שלוש או ארבע שנים לאילן זה, אין מונים את שנות ערלה ורבעי לפי ראש השנה, אלא לפי חמישה עשר בשבט? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן ומטו בה\u0004 \u0005[\u0006ויש \u0005מושכים,\u0006 מוסרים, שמועה \u0005זו]\u0006 עוד \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' ינאי: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"שלוש שנים יהיה לכם ערלים לא יאכל. \u0003ובשנה הרביעית\u0004 יהיה כל פריו קודש הילולים לה' \u0003ובשנה החמישית\u0004 תאכלו את פריו להוסיף לכם תבואתו אני ה' אלוקיכם\" (ויקרא יט, כג-כד),","שבגלל ו' החיבור שבין הפסוקים יש להבין ש\u0003פעמים ש\u0004הנטיעה כבר \u0003ב\u0004שנה ה\u0003רביעית ועדיין אסורה משום ערלה, ופעמים ש\u0004הנטיעה כבר \u0003ב\u0004שנה ה\u0003חמישית ועדיין אסורה משום רבעי.\u0004","ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שהלכה זו ש\u0003לא כ\u0004שיטת \u0003ר' מאיר, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' מאיר\u0004 היא — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 ר' מאיר: \u0003יום אחד בשנה חשוב שנה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פר האמור בתורה סתם\u0004 הרי הוא \u0003בן עשרים וארבעה חדש ויום אחד,\u0004 שאף שמסורת בידינו שפר הוא בן שלוש שנים, לאו דווקא שלוש שנים מליאות הן, אלא כיון שנכנס יום אחד בשלישית הרי הוא כבן שלוש. אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' אלעזר אומר: בן עשרים וארבעה חדש ושלשים יום. שהיה ר' מאיר אומר: כל מקום שנאמר \"עגל\" בתורה סתם\u0004 — הרי הוא \u0003בן שנה,\u0004 אם נאמר \u0003\"בן בקר\"\u0004 — הרי הוא \u0003בן שתים,\u0004 ואם נאמר \u0003\"פר\"\u0004 — הרי הוא \u0003בן שלש.\u0004 וכיון שהברייתא לענין נטיעות סבורה שצריך שלושים יום ואין די ביום אחד לפני ראש השנה, משמע שאינה כשיטת ר' מאיר!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003ר' מאיר,\u0004 אולם \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' מאיר\u0004 כי \u0003יום אחד בשנה חשוב שנה\u0004 — הרי זה \u0003בסוף שנה,\u0004 שיום אחד ישלים את מנין השנים כאילו היתה זו שנה שלימה, \u0003אבל בתחלת שנה\u0004 שיום אחד בתחילת החשבון ייחשב כשנה \u0003לא\u0004 אמר כן.","כנגד טענה זו \u0003אמר רבא: ולאו קל וחומר הוא\u0004 שתהא הסברה הפוכה? \u0003ומה נדה, שאין תחילת היום עולה לה בסופה\u0004 שגם אם עברו שבעה ימים משעה לשעה מתחילת ראיית הדם, והיה זה באמצע היום השביעי — אין זה נחשב לסיום טומאת נדתה, אלא ממתינה באותו יום וטובלת רק בלילה שלאחריו, ובכל זאת \u0003סוף היום עולה לה בתחלתה,\u0004 שאם ראתה דם נדה זמן קצר לפני הערב השמש, הרי יום זה נמנה כיום ראשון לימי נדתה. משמע שיום אחד בתחלה נחשב יותר למנין מאשר יום בסוף המנין. ואם כן \u0003שנה, שיום אחד עולה לה\u0004 (נחשב ונמנה) \u0003בסופה,\u0004"],["\u0003אינו דין שיום אחד עולה בתחלתה?\u0004","ושואלים: אם כן, לצד שהוכחנו לכאורה שהברייתא אינה כשיטת רבי מאיר \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר שהברייתא כשיטת \u0003ר' אלעזר\u0004 שרק שלושים יום בשנה נחשבים כשנה — אולם לדעתו \u0003שלשים ושלשים בעי\u0004 \u0005[צריך]!\u0006 שלושים יום לקליטת הנטיעה בקרקע ושלושים נוספים כדי להחשיבה כבת שנה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין נוטעין ואין מבריכין ואין מרכיבין\u0004 נטיעות ב\u0003ערב\u0004 השנה ה\u0003שביעית פחות משלשים יום לפני ראש השנה, ואם נטע והבריך והרכיב\u0004 — \u0003יעקור,\u0004 שכן ודאי נקלטה הנטיעה בשביעית וגידולי שביעית אסורים בהנאה, אלו \u0003דברי ר' אלעזר. ר' יהודה אומר: כל הרכבה שאינה קולטת בשלשה ימים\u0004 — \u0003שוב אינה קולטת. ר' יוסי ור' שמעון אומרים: שתי שבתות\u0004 הוא זמן קליטה.","\u0003ואמר רב נחמן אמר רבה בר אבוה: לדברי האומר שלשים\u0004 יום, כוונתו כי \u0003צריך שלשים ושלשים,\u0004 שלושים לקליטה ושלושים להפסקה, \u0003לדברי האומר שלשה\u0004 — \u0003צריך שלשה ושלשים, ולדברי האומר שתי שבתות\u0004 — \u0003צריך שתי שבתות ושלשים יום.\u0004 ולכן \u0003אי נמי\u0004 \u0005[אם גם כן]\u0006 תאמר כשיטה המפחיתה ביותר בזמן קליטה, שהיא שיטת \u0003ר' יהודה,\u0004 הרי גם אז \u0003שלשה ושלשים בעי\u0004 \u0005[צריך]!\u0006 ואם כן אין הדברים מתיישבים אף לשיטת רבי אלעזר!","\u0003אלא\u0004 יש לחזור ממה שאמרנו ו\u0003לעולם\u0004 יש לומר כי הברייתא היא כשיטת \u0003ר' מאיר. וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 ר' מאיר \u0003שלשים\u0004 יום, הרי כוונתו היתה \u0003לענין קליטה\u0004 שהיא שלושים יום.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003שלשים ואחד בעי\u0004 \u0005[צריך הוא]!\u0006 שלושים יום לקליטה, ועוד יום אחד שייחשב להתחלת השנה! ומשיבים: בעצם כך הוא החשבון, אלא \u0003קא סבר\u0004 \u0005[סבור הוא]:\u0006 \u0003יום שלשים עולה\u0004 (נחשב) \u0003לכאן ולכאן,\u0004 שיום זה עצמו נחשב כהשלמת יום השלושים לימי הקליטה, וגם נחשב כיום אחד בשנה שייחשב לאותה שנה.","\u0003אמר ר' יוחנן: ושניהן,\u0004 גם רבי מאיר וגם רבי אלעזר שנחלקו מה נחשב לשנה \u0003מקרא אחד דרשו\u0004 באופנים שונים. שנאמר: \u0003\"ויהי באחת ושש מאות שנה בראשון באחד לחדש\u0004 חרבו המים מעל הארץ \u0003\"(בראשית ח, יג). ר' מאיר סבר: מדאכתי\u0004 \u0005[מכיון שעדיין]\u0006 \u0003יום אחד\u0004 בלבד \u0003הוא דעייל\u0004 \u0005[שנכנס]\u0006 \u0003בשנה,\u0004 שהרי הוא בראשון באחד בחודש \u0003וקא קרי\u0004 \u0005[והוא קורא]\u0006 \u0003לה שנה,\u0004 שהרי לא מנה שנת שש מאות אלא שנת שש מאות ואחד, אם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003יום אחד בשנה חשוב שנה.\u0004","\u0003ואידך\u0004 \u0005[והאחר]\u0006 רבי אלעזר מה הוא אומר? \u0003אי כתיב\u0004 \u0005[אילו היה כתוב]\u0006 \u0003בשש מאות ואחת שנה\u0004 הייתי אכן מפרש \u0003כדקאמרת\u0004 \u0005[כפי שאתה אומר],\u0006 אולם \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"באחת ושש מאות שנה\",\u0004 כך צריך להבין: המלה \u0003\"שנה\"\u0004 על ה\u0003שש מאות קאי\u0004 \u0005[עומדת,\u0006 שייכת\u0005],\u0006 לומר שהשנה היא עדיין שנת שש מאות. \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003\"אחת\"\u0004 שנאמר — \u0003אתחלתא\u0004 \u0005[ההתחלה]\u0006 של \u0003אחת קאמר\u0004 \u0005[אמר].\u0006","ושואלים: \u0003ור' אליעזר מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטתו, מהיכן לומד הוא כדבריו? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בראשון באחד לחדש\", מדאכתי\u0004 \u0005[מכיון שעדיין]\u0006 \u0003יום אחד הוא\u0004 רק \u0003דעייל\u0004 \u0005[שנכנס]\u0006 \u0003בחדש וקא קרי ליה\u0004 \u0005[והוא קורא לו]\u0006 \u0003חדש\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003יום אחד בחדש חשוב\u0004 (נחשב) ל\u0003חדש, ומ\u0004זה ש\u0003יום אחד בחדש\u0004 נחשב ל\u0003חדש,\u0004 אם כן בדרך זו יש לומר אף כי \u0003שלשים יום בשנה חשובין שנה.\u0004 כי \u0003חדש\u0004 חושבים אותו \u0003ל\u0004פי \u0003מנוייו\u0004 והחודש הרי הוא נמנה משלושים ימים, \u0003ושנה למנוייה\u0004 ומניינה על פי שנים עשר חודשים.","ומעירים: \u0003מכלל\u0004 דבריהם עולה \u0003דתרוייהו סבירא להו\u0004 \u0005[ששניהם סבורים]\u0006 כי \u0003בניסן נברא העולם,\u0004 ומחודש ניסן מונים את השנים. כי אם היתה תחילת המנין בתשרי אם כן באחד לחודש הראשון (חודש ניסן) הוא כבר חצי שנה לאחר התחלתה של השנה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 שנחלקו בכך תנאים. \u0003ר' אליעזר אומר: ב\u0004חודש \u0003תשרי נברא העולם, בתשרי נולדו\u0004 ה\u0003אבות, בתשרי מתו אבות, בפסח נולד יצחק\u0004 אבינו, \u0003בראש השנה נפקדה\u0004 בילדים \u0003שרה רחל וחנה, בראש השנה יצא יוסף מבית האסורין.\u0004"],["\u0003בראש השנה בטלה עבודה מאבותינו במצרים, בניסן נגאלו\u0004 אבותינו ויצאו ממצרים, \u0003בתשרי עתידין ליגאל\u0004 גאולה האחרונה על ידי המשיח.","ואילו \u0003ר' יהושע אומר: בניסן נברא העולם, בניסן נולדו אבות, בניסן מתו אבות, בפסח נולד יצחק, בראש השנה נפקדה שרה רחל וחנה, בראש השנה יצא יוסף מבית האסורין, בראש השנה בטלה עבודה מאבותינו במצרים, בניסן נגאלו\u0004 ממצרים וכן \u0003בניסן עתידין ליגאל\u0004 גאולה אחרונה.","את הדברים הללו מפרטים ומפרשים; \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: מנין שב\u0004חודש \u0003תשרי נברא העולם\u0004 — \u0003שנאמר: \"ויאמר אלהים תדשא הארץ דשא עשב מזריע זרע עץ פרי\u0004 עושה פרי למינו\u0003\"\u0004 (בראשית א, יא). \u0003איזהו חדש שהארץ מוציאה דשאים ו\u0004באותה שעה גם ה\u0003אילן מלא פירות\u0004 בשלים — \u0003הוי אומר זה תשרי.\u0004 וראיה לדבר שבתשרי נברא העולם, שהרי העולם צריך בראשית קיומו לגשמים כדי שיוכל להצמיח, \u0003ואותו הפרק זמן רביעה\u0004 (זמן ירידת גשמים) \u0003היתה, וירדו גשמים וצימחו\u0004 כל הצמחים, \u0003שנאמר: \"ואד יעלה מן הארץ\u0004 והשקה את כל פני האדמה\u0003\"\u0004 (בראשית ב, ו).","\u0003ר' יהושע אומר: מנין שבניסן נברא העולם\u0004 — \u0003שנאמר: \"ותוצא הארץ דשא עשב מזריע זרע\u0004 למינהו \u0003ועץ עשה פרי\"\u0004 (בראשית א, יב). \u0003איזהו חדש שהארץ מליאה דשאים ואילן מוציא פירות,\u0004 כלומר, יוצר, חונט, את פירותיו — \u0003הוי אומר זה ניסן. ואותו הפרק זמן בהמה חיה ועוף שמזדווגין זה אצל זה, שנאמר: \"לבשו כרים הצאן\u0004 ועמקים יעטפו בר יתרועעו אף ישירו\u0003\"\u0004 (תהלים סה, יד).","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר,\u0006 ר' אליעזר, \u0005גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"עץ עשה פרי\"\u0004 שמשמעו העץ בזמן שהוא יוצר את הפירות! ומשיבים: הפסוק \u0003ההוא לברכה לדורות הוא דכתיב\u0004 \u0005[שנאמר].\u0006 שאין הכוונה שבאותה שעה היה העץ יוצר את פירותיו, אלא לדורות יהא כל עץ מוציא פירות.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"עץ פרי\"\u0004 ומשמע שיש בו כבר פירות? ומשיבים: הפסוק \u0003ההוא\u0004 נאמר \u0003כ\u0004דברי \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: כל מעשה בראשית ב\u0004מלוא \u0003קומתן\u0004 ובמלוא גידולם \u0003נבראו\u0004, שהיו ראויים לטעון מיד פירות, ופירותיהם \u0003לדעתן\u0004 (לרצונם) \u0003נבראו, לצביונן\u0004 (ביופיים) \u0003נבראו, שנאמר: \"ויכלו השמים והארץ וכל צבאם\"\u0004 (בראשית ב, א), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"צבאם\" אלא\u0004 קרא \u0003\"צביונם\"\u0004 (יפים) ואם כן נבראו כל הבריות, ובכללם העצים, מלאים ובשלים.","\u0003ר' אליעזר אומר: מנין שב\u0004חודש \u0003תשרי נולדו\u0004 ה\u0003אבות\u0004 — \u0003שנאמר: \"ויקהלו אל המלך שלמה כל איש ישראל בירח האתנים בחג\u0004 הוא החודש השביעי \u0003\"(מלכים א' ח, ב), מהו \"ירח האיתנים\"\u0004 — \u0003ירח שנולדו בו איתני עולם,\u0004 הם האבות.","\u0003מאי משמע\u0004 \u0005[מה משמעו],\u0006 מהיכן נובע \u0003דהאי \"איתן\" לישנא דתקיפי\u0004 \u0005[ש\"איתן\" זה לשון תוקף]\u0006 \u0003הוא\u0004 — \u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"איתן מושבך\u0004 ושים בסלע קינך \u0003\"(במדבר כד, כא). ו\u0004כן הוא \u0003אומר: \"שמעו הרים את ריב ה' והאתנים מוסדי ארץ\"\u0004 (מיכה ו, ב), שמתפרש כקריאה לאבות האומה. \u0003ואומר: \"קול דודי הנה זה בא מדלג על ההרים מקפץ על הגבעות\"\u0004 (שיר השירים ב, ח). ופירשוהו \u0003\"מדלג על ההרים\"\u0004 — שהקדים בגאולה \u0003בזכות אבות\u0004 שנקראו \"הרים\" כאמור; \u0003\"מקפץ על הגבעות\"\u0004 — \u0003בזכות אמהות.\u0004","ואילו \u0003ר' יהושע אומר: מנין שבניסן נולדו אבות\u0004 — \u0003שנאמר: \"ויהי בשמונים שנה וארבע מאות שנה לצאת בני ישראל מארץ מצרים בשנה הרביעית בחדש זו\"\u0004 (מלכים א' ו, א), ומהו \"בחודש זיו\" — \u0003בירח שנולדו בו זיותני עולם\u0004 (היפים שבעולם) שהם האבות.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"בירח האתנים\"!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 פירושו \u0003דתקיפי\u0004 \u0005[ש\u0006הם \u0005חזקים]\u0006 \u0003במצות.\u0004","ושואלים עוד: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"בחדש זו\"!\u0004 ומשיבים: \"זיו\" אינו כינוי לאבות, אלא לומר: \u0003דאית ביה זיוא לאילני\u0004 \u0005[שיש בו זיו\u0006 ויופי \u0005לאילנות].\u0006 וכפי ש\u0003אמר רב יהודה: האי מאן דנפק ביומי\u0004 \u0005[מי שיוצא בימי]\u0006 \u0003ניסן וחזי אילני דמלבלבי\u0004 \u0005[ורואה אילנות המלבלבים]\u0006 \u0003אומר\u0004 ברכה זו: \u0003ברוך שלא חיסר מעולמו כלום וברא בו בריות טובות ואילנות טובות להתנאות בהן בני אדם.\u0004","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003בניסן נולדו\u0004 האבות, ממילא סבור הוא גם כן כי \u0003בניסן מתו,\u0004 וכן \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003בתשרי נולדו,\u0004 סבור הוא כי \u0003בתשרי\u0004 אף \u0003מתו. שנאמר\u0004 במשה: \u0003\"ויאמר אלהם בן מאה ועשרים שנה אנכי היום\"\u0004 (דברים לא, ב), \u0003שאין תלמוד לומר \"היום\",\u0004 שהרי ברור שהוא מדבר ביום זה, \u0003ומה תלמוד לומר \"היום\"\u0004 — לומר שהוא מתכוון ליום זה ממש, \u0003היום מלאו ימי ושנותי. ללמדך שהקדוש ברוך הוא יושב וממלא שנותיהם של צדיקים מיום ליום\u0004 ו\u0003מחדש לחדש, שנאמר: \"את מספר ימיך אמלא\"\u0004 (שמות כג, כו), וודאי גם האבות זכו שמלאו ימיהם ומתו ביום שנולדו בו.","\u0003בפסח נולד יצחק מנלן\u0004 \u0005[מניין לנו]\u0006 — \u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"למועד אשוב אליך\u0004 כעת חיה ולשרה בן\u0003\"\u0004 (בראשית יח, יד), ופירושו: בזמן החג (מועד) הבא. ונברר: \u0003אימת קאי\u0004 \u0005[אימתי עמד]\u0006 ואמר דבר זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה זה \u0003בפסח וקאמר ליה\u0004 \u0005[ואמר לו]\u0006 שיולד הבן במועד הבא \u0003בעצרת\u0004 (חג השבועות) — \u0003בחמשין יומין מי קא ילדה\u0004 \u0005[בחמישים יום האם יולדת\u0006 אשה\u0005]?\u0006 \u0003אלא\u0004 תאמר \u0003דקאי\u0004 \u0005[שהוא עמד]\u0006 \u0003בעצרת וקאמר ליה\u0004 \u0005[ואמר לו]\u0006 שתלד \u0003בתשרי\u0004 — \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003בחמשה ירחי מי קא ילדה\u0004 \u0005[בחמישה חודשים\u0006 האם \u0005היא יולדת]?\u0006 \u0003אלא דקאי\u0004 \u0005[שעמד]\u0006 \u0003בחג\u0004 (הסוכות) בתשרי \u0003וקאמר\u0004 \u0005[ואמר]\u0006 \u0003לה\u0004 בחג כי \u0003ב\u0004חודש \u0003ניסן\u0004 תלד.","ושואלים: \u0003אכתי, בשיתא ירחי מי קא ילדה\u0004 \u0005[עדיין בשישה חודשים האם\u0006 אשה \u0005יולדת]?\u0006 \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אותה שנה מעוברת היתה.\u0004 ותוהים: \u0003סוף סוף כי מדלי מר יומי\u0004 \u0005[אם תוציא את ימי]\u0006 ה\u0003טומאה\u0004 של נדה, הרי \u0003בצרי להו\u0004 \u0005[פוחתים הם\u0006 הימים\u0005],\u0006 שהרי באותה שעה שאמר המלאך עדיין לא נפקדה שרה, ואותו יום ראתה וסת, כמרומז בכתוב (\"אחרי בלותי היתה לי עדנה\". בראשית יח, יב) ואם כן נמצא שהם פחות משישה חודשים!","\u0003אמר מר זוטרא: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי האשה \u0003היולדת לתשעה\u0004 חודשים — \u0003אינה יולדת למקוטעין,\u0004 אלא משלימה הריון של תשעה חודשים מלאים, זו \u0003שיולדת לשבעה\u0004 חודשים מיום עיבורה — \u0003יולדת גם למקוטעין,\u0004 כלומר, גם לפחות משבעה חודשים שלמים, \u0003שנאמר\u0004 בלידת שמואל: \u0003\"ויהי לתקפות הימים\u0004 ותהר חנה ותלד בן\u0003\"\u0004 (שמואל א א, כ), ומכאן למדים: \u0003מיעוט \"תקופות\"\u0004 הן \u0003שתים, ומיעוט \"ימים\"\u0004 — \u0003שנים,\u0004 וכיון שכל תקופה נמשכת שלושה חודשים נמצא שהאשה יולדת אפילו כעבור שישה חודשים ויומיים.","שנינו כי \u0003בראש השנה נפקדה שרה רחל וחנה.\u0004 ומבררים: \u0003מנלן\u0004 \u0005[מניין לנו],\u0006 מהיכן נלמד דבר זה\u0003? אמר ר' אלעזר: אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 בגזירה שווה \u0003\"פקידה\" \"פקידה\", אתיא\u0004 \u0005[\u0006ו\u0005באה,\u0006 נלמדת\u0005]\u0006 בגזירה שווה \u0003\"זכירה\" \"זכירה\". כתיב\u0004 \u0005[נאמר]\u0006 \u0003ברחל: \"ויזכר אלהים את רחל\"\u0004 (בראשית ל, כב) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003בחנה: \"ויזכרה ה'\" (שמואל א' א, יט), ואתיא\u0004 \u0005[ובאה,\u0006 נלמדת\u0005]\u0006 \u0003\"זכירה\" \"זכירה\" מראש השנה דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שבתון זכרון תרועה\"\u0004 (ויקרא כג, כד), שהוא יום הקבוע לזכרון. ומכאן נלמד לרחל שנפקדה בראש השנה.","וכן נלמד בגזירה שווה \u0003\"פקידה\" \"פקידה\", כתיב\u0004 נאמר \u0003בחנה: \"כי פקד ה' את חנה\" (שמואל א' ב, כא) וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003בשרה: \"וה' פקד את שרה\" (בראשית כא, א), ואם כן כמו שבחנה היה בראש השנה, אף בשרה ראש השנה היה.\u0004","עוד שנינו כי \u0003בראש השנה יצא יוסף מבית האסורין, מנלן\u0004 \u0005[מנין לנו],\u0006 מהיכן נלמד הדבר — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תקעו בחדש שופר בכסא ליום חגנו. כי חק לישראל הוא\u0004 משפט לאלהי יעקב\u0003\"\u0004 (תהלים פא, ד-ה),"],["ומיד לאחר מכן נאמר: \u0003\"עדות ביהוסף שמו בצאתו\u0004 על ארץ מצרים \u0003\"(תהלים פא, ו), משמע שהיה זה סמוך לראש השנה.\u0004","עוד שנינו כי \u0003בראש השנה בטלה עבודה מאבותינו במצרים\u0004 מנין — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"והוצאתי אתכם מתחת סבלת מצרים\"\u0004 (שמות ו, ו) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 ביוסף: \u0003\"הסירותי מסבל שכמו\"\u0004 (תהלים פא, ז), וכשם שיוסף יצא מבית הסוהר בתשרי — כך גם אבותינו במצרים נגאלו מן העבודה בתשרי.","\u0003בניסן נגאלו\u0004 — \u0003כדאיתא\u0004 \u0005[כפי שמצוי\u0006 בכתובים במפורש\u0005].\u0006 \u0003בתשרי עתידין ליגאל\u0004 — \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה \u0003\"שופר\" \"שופר\". כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בראש השנה: \u0003\"תקעו בחדש שופר\"\u0004 (תהלים פא, ד) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בתיאור הגאולה לעתיד בראש השנה: \u0003\"והיה ביום ההוא יתקע בשופר גדול\"\u0004 (ישעיה כז, יג).","\u0003ר' יהושע אומר: בניסן נגאלו, בניסן עתידין ליגאל\u0004 — \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ליל שמרים\u0004 הוא לה' להוציאם מארץ מצרים הוא הלילה הזה לה' שימורים לכל בני ישראל לדורותם\u0003\"\u0004 (שמות יב, מב), ללמדנו שהוא \u0003ליל המשומר ובא מששת ימי בראשית,\u0004 שאף גאולה אחרונה (\"לדורותם\") תהיה בו.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' אליעזר מפרש כי הוא \u0003לילה המשומר ובא מן המזיקין,\u0004 שבכל הדורות לא תהיה שליטה למזיקים בליל הפסח.","ומעירים: \u0003ואזדו\u0004 \u0005[והולכים הם]\u0006 ר' אליעזר ור' יהושע \u0003לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005],\u0006 שנחלקו באותה בעיה גם במקום אחר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003: \"בשנת שש מאות שנה לחיי נח בחדש השני בשבעה עשר יום לחדש\u0004 ביום הזה נבקעו כל מעינות תהום רבה וארובות השמים נפתחו\u0003\"\u0004 (בראשית ז, יא). \u0003ר' יהושע אומר: אותו היום שבעה עשר באייר היה\u0004 שהחודש השני הוא חודש אייר, שהוא \u0003יום שמזל כימה שוקע ביום ומעינות מתמעטין\u0004 עם גבור החום, \u0003ומתוך ששינו\u0004 אנשי דור המבול \u0003מעשיהן\u0004 לרעה \u0003שינה הקדוש ברוך הוא עליהם מעשה בראשית, ו\u0004במקום שישקע מזל כימה \u0003העלה מזל כימה ביום, ונטל שני כוכבים מכימה ו\u0004על ידי כך \u0003הביא מבול לעולם.\u0004","ואילו \u0003ר' אליעזר אומר: אותו היום שבעה עשר במרחשון היה\u0004 והחודש השני הוא השני לתשרי, \u0003יום שמזל כימה עולה ביום ו\u0004בכל הזמנים \u0003מעינות מתגברים\u0004"],["\u0003ומתוך ששינו מעשיהם\u0004 לרעה \u0003שינה הקדוש ברוך הוא עליהם מעשה בראשית, והעלה מזל כימה ביום, ונטל שני כוכבים\u0004 ממנה \u0003והביא מבול לעולם.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יהושע\u0004 הסובר כי המבול החל בחודש אייר — \u0003היינו דכתיב\u0004 \u0005[זה שנאמר]:\u0006 \u0003\"החודש השני\",\u0004 שמפורש בתורה במקום אחר שהוא חודש אייר, \u0003אלא לר' אלעזר מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003\"שני\"\u0004 זה שנאמר? הלא לדבריו לא היה זה בחודש השני! ומשיבים: \u0003שני לדין\u0004 שהרי יום הדין הוא ראש השנה.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יהושע\u0004 הסובר כי המבול החל בחודש אייר, \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003שינה\u0004 מעשה בראשית, \u0003אלא לר' אליעזר מאי\u0004 \u0005[במה]\u0006 \u0003שינה?\u0004","ומשיבים: אף לדעת ר' אליעזר שינה, \u0003כ\u0004שיטתו של \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: ברותחין קלקלו ברותחין נידונו. ברותחין קלקלו\u0004 — \u0003בעבירה,\u0004 שהיו פרוצים בעריות וקלקלו בשכבת זרע (שהיא חמה) \u0003וברותחין נידונו\u0004 — שגשמי המבול היו רותחים. ומנין למדים זאת — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בענין המבול: \u0003\"וישכו המים\"\u0004 (בראשית ח, א) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 באחשורוש \u0005:\u0006 \u0003\"וחמת המלך שככה\"\u0004 (אסתר ז, י), ומכאן ששיכוך זה פירושו הצטננות מן החום.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003חכמי ישראל מונין\u0004 ומפרשים \u0003למבול\u0004 ולמנין שנות העולם \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 — מתשרי, ואת חשבון ה\u0003תקופה,\u0004 לענין חשבון תקופת החמה, מונים הם \u0003כ\u0004שיטת \u0003ר' יהושע\u0004 — מניסן, ואילו \u0003חכמי אומות העולם מונין אף למבול\u0004 ולענין סדר הדורות \u0003כ\u0004שיטת \u0003ר' יהושע\u0004 — מניסן.","שנינו במשנה שאחד בתשרי הוא ראש השנה \u0003לירקות. תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003לירקות ולמעשרות ולנדרים.\u0004 ושואלים: \u0003לירקות מאי נינהו\u0004 \u0005[מה הם]\u0006 מה עניינו? הרי הכוונה היא \u0003למעשר ירק,\u0004 שאין תורמים ומעשרים מירק שנלקט בערב ראש השנה על זה שנלקט לאחר ראש השנה,","ואם כן \u0003היינו\u0004 \u0005[הרי הוא]\u0006 \u0003מעשרות\u0004 ומדוע חילק ביניהם בברייתא? ומשיבים: \u0003תנא דרבנן וקתני דאורייתא\u0004 \u0005[שנה\u0006 את הדבר \u0005שהוא מדברי סופרים, ושנה\u0006 את הדבר שהוא \u0005מן התורה],\u0006 שמעשר דגן ויצהר הוא מן התורה וזמנו הוא באחד בתשרי, וירק שמצות עישורו היא מדברי סופרים, אף זמנו בתשרי.","ושואלים: \u0003אם כן, וליתני דאורייתא ברישא\u0004 \u0005[ושישנה\u0006 את הדבר שהוא \u0005מן התורה בראשונה]!\u0006 ומשיבים: \u0003איידי דחביבא ליה אקדמה\u0004 \u0005[כיון שחביבה לו\u0006 ההלכה \u0005הקדים אותה],\u0006 שמקדימים תחילה דבר שיש בו חידוש, ולכך שנה תחילה ירקות שאין מצות עישורם אלא מדברי סופרים, ואחר כך שנה מעשרות. ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו],\u0006 במשנתנו שלא שנה מעשרות מה טעמו? ומסבירים: הוא \u0003תנא דרבנן\u0004 \u0005[שנה\u0006 מעשר ירק שהוא \u0005מדברי סופרים]\u0006 \u0003וכל שכן\u0004 מעשרות \u0003דאורייתא\u0004 \u0005[שמן התורה].\u0006","ושואלים שוב על התוספתא: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"מעשר\"\u0004 בלשון יחיד, ומדוע שנה בלשון רבים \"מעשרות\"? ומשיבים: הוא סבור \u0003אחד מעשר בהמה ואחד מעשר דגן.\u0004 ושואלים עוד: מדוע שנה \"ירקות\" בלשון רבים, \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"ירק\"!\u0004 ומשיבים: \u0003תרי גווני\u0004 \u0005[שני מיני]\u0006 \u0003ירק\u0004 נרמזו בכך, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ירק הנאגד,\u0004 כלומר, מין ירק שדרך לאגוד אותו באגודות טרם מכירתו — הזמן שחלה עליו חובת מעשר הוא \u0003משיאגד, ושאינו נאגד\u0004 — לא חלה עליו חובת מעשר אלא \u0003משימלא את הכלי\u0004 שאליו לוקט אותו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003ליקט ירק ערב ראש השנה עד שלא תבא השמש,\u0004 לפני ששקעה החמה, ובאשר על כן שייך הוא עדיין לשנה הקודמת, \u0003וחזר וליקט\u0004"],["\u0003משתבא השמש,\u0004 משכבר שקעה, שהוא כבר שייך לשנה הבאה — \u0003אין תורמין ומעשרין מזה על זה, לפי שאין תורמין ומעשרין לא מן החדש על הישן ולא מן הישן על החדש.\u0004 וכן \u0003אם היתה\u0004 זו שנה \u0003שניה\u0004 משנות השמיטה \u0003הנכנסת ל\u0004שנה ה\u0003שלישית,\u0004 הרי מה שילקט בשנה ה\u0003שניה\u0004 מפריש ממנו \u0003מעשר ראשון, ומעשר שני\u0004 שאוכלו בירושלים, ומן השייך לשנה ה\u0003שלישית\u0004 מפריש \u0003מעשר ראשון ומעשר עני.\u0004","לגופו של ענין שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שבשנה השלישית אין מפרישים מעשר שני אלא מעשר עני? \u0003אמר ר' יהושע בן לוי:\u0004 נאמר, \u0003\"כי תכלה לעשר את כל מעשר תבואתך בשנה השלישית שנת המעשר\"\u0004 (דברים כו, יב), לומר: \u0003שנה שאין בה אלא מעשר אחד. הא כיצד?\u0004 מפריש \u0003מעשר ראשון, ומעשר עני\u0004 שמפורש באותו ענין. \u0003ומעשר שני יבטל,\u0004 באותה שנה.","ושמא תאמר: \u0003או אינו אלא\u0004 הכוונה ש\u0003אף מעשר ראשון נמי\u0004 \u0005[גם כן]\u0006 \u0003יבטל,\u0004 ויפריש רק מעשר אחד בלבד — \u0003תלמוד לומר: \"ואל הלוים תדבר ואמרת אלהם כי תקחו מאת בני ישראל את המעשר אשר נתתי לכם מאתם בנחלתכם\"\u0004 (במדבר יח, כו), \u0003הקישו\u0004 (השווה אותו) \u0003הכתוב\u0004 את המעשר \u0003לנחלה, מה נחלה אין לה הפסק\u0004 שהרי מדין תורה אי אפשר למכור אחוזת נחלה שבארץ והיא עוברת מדור לדור ואין בה הפסק — \u0003אף מעשר ראשון\u0004 שניתן ללויים כנחלה הוא, \u0003אין לו הפסק,\u0004 ולכן עלינו לומר שהוא ניתן בכל שנה ושנה בלי הפסק.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"כי תכלה לעשר\u0004 בשנה השלישית, שנת המעשר\" — \u0003שנה שאין בה אלא מעשר אחד. הא כיצד\u0004 — \u0003מעשר ראשון ומעשר עני, ומעשר שני יבטל. יכול אף מעשר ראשון נמי\u0004 \u0005[גם כן]\u0006 \u0003יבטל\u0004 — \u0003תלמוד לומר: \"ובא הלוי\u0004 כי אין לו חלק ונחלה עמך והגר והיתום והאלמנה אשר בשעריך ואכלו ושבעו\" (דברים יד, כט), לומר: \u0003כל זמן שבא\u0004 — \u0003תן לו.\u0004 משמע בכל שנה ושנה צריך לתת לו מעשר, אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' אליעזר בן יעקב אומר: אינו צריך\u0004 ללומדו מכאן, אלא \u0003הרי הוא אומר \"ואל הלוים תדבר ואמרת אלהם כי תקחו מאת בני ישראל את המעשר אשר נתתי לכם מאתם בנחלתכם\u0004 והרמותם ממנו תרומת ה' מעשר מן המעשר\u0003\"\u0004 (במדבר יח, כו) \u0003הקישו\u0004 (השווה אותו) \u0003הכתוב לנחלה: מה נחלה אין לה הפסק\u0004 — \u0003אף מעשר ראשון אין לו הפסק.\u0004","שנינו בברייתא כי באחד בתשרי ראש השנה \u0003לנדרים. תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003המודר הנאה מחבירו לשנה\u0004 שנדר שבמשך שנה אחת לא יהנה ממנו — \u0003מונה שנים עשר חודש מיום ליום\u0004 מאותו יום שנדר. \u0003ואם אמר\u0004 שהוא מודר ממנו \u0003לשנה זו, אפילו לא עמד\u0004 ונדר \u0003אלא בעשרים ותשעה באלול, כיון שהגיע יום אחד בתשרי\u0004 — \u0003עלתה לו שנה\u0004 ואינו נוהג איסור בשנה הבאה.","\u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 בדרך כלל כי \u0003יום אחד בשנה אינו חשוב שנה\u0004 מסכים הוא להלכה זו כי \u0003לצעוריה נפשיה קביל עליה\u0004 \u0005[לצער את עצמו קיבל עליו]\u0006 \u0003והא אצטער ליה\u0004 \u0005[והרי\u0006 כבר \u0005הצטער לו]\u0006 ויצא ידי חובת הנדר, שהרי קיים משהו ממנו.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ששנה זו של נדר תהא עד \u0003ניסן?\u0004 ומשיבים: כלל הוא כי \u0003בנדרים הלך אחר לשון בני אדם\u0004 כי אין דנים את הנדרים אלא לפי הנהוג בלשון הדיבור המצוי בין אנשים, ובלשון הדיבור מונים שנה מאחד בתשרי.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת מעשרות: מתי הוא הזמן שבו ולפיו אנו מונים את שנת המעשר? לגבי \u0003התלתן\u0004 — \u0003משתצמח,\u0004 לגבי \u0003התבואה, והזיתים\u0004 — \u0003משיביאו שליש\u0004 בישולם, אותה שעה קובעת למעשרות בכל שנה שהיא.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003משתצמח\u0004 — הלא הצמח צומח כמעט משעת זריעתו! אלא הכוונה היא \u0003משתצמח לזרעים\u0004 כלומר, שמתחילים כבר לצמוח הזרעים בתוך הצמח.","שנינו כי \u0003התבואה\u0004 (דגן ותירוש) \u0003והזיתים,\u0004 זמנם למעשר \u0003משיביאו שליש,\u0004 כלומר, כשיגיעו לשליש בישולם. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 לגבי קביעת זמן מסויים כקובע את השנה לענין מעשר היבולים? \u0003אמר רב אסי אמר ר' יוחנן, ומטו בה\u0004 \u0005[והיו ממשיכים אותה\u0006 את השמועה הזו\u0005]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוסי הגלילי: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מקץ שבע שנים במעד שנת השמטה בחג הסכות\"\u0004 (דברים לא, י) ולכאורה תמוה: \u0003שנת השמטה מאי עבידתיה\u0004 \u0005[מה מעשיה]\u0006 מה היא שייכת ל\u0003חג הסוכות?\u0004 הלא חג הסוכות תחילת השנה ה\u0003שמינית היא!\u0004","\u0003אלא,\u0004 כפי שבכתוב זה רואים שזמן חג הסוכות נחשב כאילו היה שייך לשנה שעברה, הרי זה בא \u0003לומר לך:\u0004 ש\u0003כל תבואה שהביאה שליש ב\u0004שנה ה\u0003שביעית\u0004 (השמיטה) \u0003לפני ראש השנה\u0004 — \u0003אתה נוהג בו\u0004 ביבול זה \u0003מנהג\u0004 וקדושת שנת ה\u0003שביעית\u0004 גם אם השימוש וגמר הפרי הוא \u0003ב\u0004שנה ה\u0003שמינית.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרב אסי:\u0004"],["\u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא עייל\u0004 \u0005[נכנס]\u0006 \u0003כלל,\u0004 אפילו אם לא הבשילה התבואה כלל בשביעית, בכל זאת \u0003וקאמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003תשמט ותיזיל\u0004 \u0005[ותלך]\u0006 שנת השמיטה \u0003עד חג הסוכות,\u0004 שכל חיובי השמיטה נמשכים עד לסוכות!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וחג האסף בצאת השנה\u0004 באספך את מעשיך מן השדה\u0003\"\u0004 (שמות כג, טז), \u0003מאי\u0004 \u0005[מה]\u0006 פירושו של \u0003\"אסיף\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שמשמעו: \u0003חג הבא בזמן אסיפה\u0004 — \u0003הכתיב\u0004 \u0005[הלא\u0006 כבר \u0005נאמר]\u0006 פעם אחת: \u0003\"באספך\"\u0004 ואין צורך לאמר זאת שנית.","\u0003אלא מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אסיף\"\u0004 כאן — \u0003קציר. וקים להו לרבנן\u0004 \u0005[ומוחזק להם לחכמים]\u0006 ש\u0003כל תבואה שנקצרה בחג\u0004 שזה היה גמר בישולה \u0003בידוע ש\u0004כבר \u0003הביאה שליש\u0004 בישולה \u0003לפני ראש השנה, וקא קרי לה\u0004 \u0005[והוא קורא אותה]\u0006 את עונת השנה עד חג הסוכות \u0003\"בצאת השנה\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא\u0004 לאחר ששמע דברים אלה: \u0003וקים להו לרבנן\u0004 \u0005[\u0006וכי \u0005מוחזק להם לחכמים]\u0006 וידוע להם ההבדל המדוייק \u0003בין שליש לפחות משליש? אמר ליה\u0004 \u0005[לו]\u0006 רב זירא: \u0003לאו אמינא לך\u0004 \u0005[וכי לא אמרתי לך]\u0006 \u0003לא תפיק נפשך לבר מהלכתא\u0004 \u0005[אל תוציא את עצמך מחוץ ל\u0006גדרי \u0005ההלכה]?\u0006 שהרי \u0003כל מדות חכמים כן הוא,\u0004 שיש להם שיעורים וגבולות מדוייקים,","כגון \u0003בארבעים סאה\u0004 של מים \u0003הוא טובל\u0004 ונטהר, אולם \u0003בארבעים סאה חסר קורטוב (משהו)\u0004 — \u0003אינו יכול לטבול בהן.\u0004 וכן מאכל ששיעורו \u0003כביצה מטמא טומאת אוכלין, כביצה חסר\u0004 מידה קטנה ואפילו רק כ\u0003שומשום\u0004 — \u0003אינו מטמא טומאת אוכלין,\u0004 וכן בגד שיש כו","\u0003שלשה על שלשה\u0004 טפחים — \u0003מטמא\u0004 טומאת \u0003מדרס\u0004 אם ישב עליו הזב, ואילו בגד של \u0003שלשה על שלשה חסר נימא\u0004 (חוט) \u0003אחת\u0004 — \u0003אינו מטמא מדרס.\u0004","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר ר' ירמיה\u0004 עצמו: \u0003לאו מילתא היא דאמרי\u0004 \u0005[אין זה דבר מה שאמרתי]\u0006 כלומר, השאלה ששאלתי אין לה בסיס שהרי אפשר להוכיח שיודעים חכמים את ההבדל. \u0003דבעו מיניה חבריא\u0004 \u0005[ששאלו בני החבורה,\u0006 החכמים \u0005ממנו]\u0006 \u0003מרב כהנא: עומר שהקריבו ישראל בכניסתן לארץ\u0004 בשנה הראשונה שבאו עם יהושע, \u0003מהיכן הקריבוהו,\u0004 מהיכן מצאו עומר זה לקצור? \u0003אם תאמר\u0004 שעומר זה הוא מתבואה שגדלה \u0003דעייל\u0004 \u0005[שהביאה,\u0006 שגדלה\u0005]\u0006 \u0003ביד גוי,\u0004 הלא \u0003\"קצירכם\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא קציר גוי.\u0004","ותוהים קודם כל על עצם הדברים: \u0003ממאי דאקריבו\u0004 \u0005[מניין\u0006 לך \u0005שהקריבו]\u0006 עומר בשנה זו, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא אקריבו\u0004 \u0005[הקריבו]!\u0006 ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"ויאכלו מעבור הארץ ממחרת הפסח\"\u0004 (יהושע ה, יא), ללמדנו: רק \u0003ממחרת הפסח\u0004 — \u0003אכול\u0004 \u0005[אכלו]\u0006 מתבואת הארץ, אולם \u0003מעיקרא\u0004 \u0005[מקודם,\u0006 מתחילה\u0005]\u0006 \u0003לא אכול\u0004 \u0005[אכלו].\u0006 ומדוע — \u0003דאקריבו\u0004 \u0005[שהקריבו]\u0006 \u0003עומר\u0004 בשישה עשר כדינו \u0003והדר אכלי\u0004 \u0005[ואחר כך אכלו]\u0006 שאם לא הקריבו עומר כלל ולא חל חיוב זה עליהם — לא היה להם לחלק בין קודם הפסח ואחר הפסח, ויש איפוא לשאול: \u0003מהיכן הקריבו?\u0004","\u0003אמר להן\u0004 רב כהנא: \u0003כל שלא הביא שליש ביד גוי,\u0004 ונמסר ביד ישראל ונגמר בישולו — הרי הוא ראוי לקצירה לשם עומר.","ואמר ר' ירמיה: הרי גם שם אפשר היה לשאול: \u0003ודלמא עייל ולא קים להו\u0004 \u0005[ושמא כבר הביא\u0006 שליש \u0005ולא מוחזק להם\u0006 לחכמים\u0005]\u0006 ואינם יודעים את ההבדל המדוייק? \u0003אלא\u0004 על כרחך עליך לומר כי \u0003קים להו\u0004 \u0005[מוחזק להם]\u0006 בדיוק — \u0003הכא נמי קים להו\u0004 \u0005[כאן גם כן מוחזק בידם].\u0006","ומקשים: אף זו אינה ראיה גמורה \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אז \u0003לא עייל\u0004 \u0005[הביאה,\u0006 צמחה התבואה\u0005]\u0006 \u0003כלל\u0004 לפני שכבשו את הארץ, וניכר ההבדל לכל, \u0003אבל היכא דעייל ריבעא\u0004 \u0005[במקום שהביאה,\u0006 שהגיעה, לכלל \u0005רבע]\u0006 בישולה — \u0003בין שליש לפחות משליש לא קים להו\u0004 \u0005[מוחזק להם]\u0006 ואין הם יודעים את ההבדל!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והעם עלו מן הירדן בעשור לחדש\u0004 הראשון\u0003\"\u0004 (יהושע ד, יט), \u0003ואי סלקא דעתך\u0004 \u0005[ואם יעלה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003לא עייל\u0004 \u0005[הביאה]\u0006 \u0003כלל\u0004 — \u0003בחמשה יומי\u0004 \u0005[ימים]\u0006 \u0003מי קא מליא\u0004 \u0005[האם היא מתמלאה]\u0006 ממצב בו היא כבוסר גמור עד להבשלה מלאה?","את ההוכחה הזאת דוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומר אתה \u0003דעייל רבעא\u0004 \u0005[שנכנס\u0006 מתחילה כדי \u0005רבע]\u0006 \u0003או דנקא\u0004 \u0005[שישית]\u0006 \u0003אכתי\u0004 \u0005[עדיין]\u0006 יכול אתה לומר \u0003בחמשה יומי מי קא מליא\u0004 \u0005[האם היא מתמלאה]?\u0006 \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 להשיב — כי \u0003\"ארץ צבי\"\u0004 (דניאל יא, טו) \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 בארץ ישראל, ששבח הארץ הוא שפירותיה מתבשלים במהירות רבה כמרוץ הצבי, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יכול אתה לומר כי \u0003\"ארץ צבי\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה,\u0004 שיכולה התבואה להבשיל מראשיתה עד גמרה במשך ימים אלה.","מצד אחר \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' חנינא\u0004 על עצם ההוכחה מן הכתוב \"באספך\" לענין שנת השמיטה: \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר]\u0006 \u0003דהאי\u0004 \u0005[שזה]\u0006 \u0003\"אסיף\"\u0004 האמור בסוכות \u0003קציר הוא? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"באספך מגרנך ומיקבך\"\u0004 (דברים טז, יג) \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003בפסולת גורן ויקב הכתוב מדבר\u0004 שבהם מסככים את הסוכה. ואם כן \"אסיף\" זה האמור בחג הסוכות אינו שייך לקציר אלא לאיסוף הקש מן הגורן!","\u0003אמר ר' זירא\u0004 על כך: \u0003הא מילתא הואי בידן\u0004 \u0005[דבר זה היה בידינו]\u0006 כלומר, היה נראה לי שיש לנו ראיה טובה, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' חנינא שדא ביה נרגא\u0004 \u0005[הטיל בו גרזן]\u0006 וקצצו. שקושייתו של ר' חנינא ביטלה לגמרי הוכחה זו.","ושואלים: \u0003אלא\u0004 לאחר הדחיה הזו \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 מקור ההלכה שזמן מעשרות התבואה נחשב משעה שהביאה שליש? ומשיבים: \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יונתן בן יוסף אומר:\u0004 נאמר \u0003\"ועשת את התבואה לשלש השנים\"\u0004 (ויקרא כה, כא),"],["\u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"לשלש\" אלא \"לשליש\"\u0004 ומכאן למדנו ששליש בישול התבואה הוא התאריך הקובע לגבי חשבון המעשר.","ומקשים: \u0003והא מיבעי ליה לגופיה\u0004 \u0005[והרי צריך הוא לגופו]\u0006 שתבא ברכה בתבואה בשנה שלפני השמיטה! ומשיבים: \u0003כתיב קרא אחרינא\u0004 \u0005[נאמר כתוב אחר]:\u0006 \u0003\"וזרעתם את השנה השמינת ואכלתם מן התבואה ישן עד השנה התשיעת\"\u0004 (ויקרא כה, כב) ואם כן פסוק נותר לדרשה — לא \"לשלוש\" אלא \"לשליש\".","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה: \u0003האורז והדוחן והפרגין והשומשמין שהשרישו לפני ראש השנה\u0004 של שמיטה \u0003מתעשרים לשעבר,\u0004 כלומר, מפרישים מהם את המעשר הראוי להיות מופרש בשנה הקודמת (שנה ראשונה, שניה, רביעית וחמישית — מעשר שני. שלישית ושישית — מעשר עני), \u0003ומותרין בשביעית,\u0004 אם היתה זו שנת השמיטה. \u0003ואם לאו,\u0004 שלא השרישו לפני ראש השנה — \u0003אסורין בשביעית,\u0004 אם היתה זו שנת שמיטה, \u0003ומתעשרין לשנה הבאה,\u0004 כלומר, כמעשר הראוי לאותה שנה שבה נלקטו, אם אינה שנת השמיטה.","\u0003אמר רבה: אמור רבנן\u0004 \u0005[אמרו חכמים]\u0006 שנת ה\u0003אילן\u0004 לענין המעשר נקבעת \u0003בתר\u0004 \u0005[אחר,\u0006 לפי\u0005]\u0006 זמן ה\u0003חנטה\u0004 (יצירת צורת הפרי), \u0003תבואה וזיתים\u0004 הולכים \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003שליש\u0004 בישולם, \u0003ירק\u0004 הולך \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003לקיטה,\u0004 שזמן לקיטתו הוא הזמן הקובע לענין מעשר. והשאלה היא: \u0003הני כמאן שוינהו רבנן\u0004 \u0005[אלה\u0006 האורז והדוחן \u0005כמו מה עשו אותם חכמים]\u0006 שהרי אינם נקבעים לא לחנטה לא לשליש ולא ללקיטה!","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבה: מתוך שעשויין פרכין פרכין\u0004 שאין בשלים כולם כאחד, אלא נלקטים מעט מעט באגודות ופורכים אותם לאכילה, ואם נלך אחר זמן הלקיטה יבואו לטעות ולהפריש מהנלקט לפני ראש השנה על הנלקט לאחר ראש השנה ולהיפך, ולכן \u0003אזלי רבנן\u0004 \u0005[הולכים חכמים]\u0006 \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003השרשה,\u0004 שהוא זמן אחיד עבור כל השדה, שכל השדה משרישה בשנה אחת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ו\u0004מדוע יעשו כך? \u0003יצבור גורנו לתוכו\u0004 ויניח את הפירות הללו במקום אחד ויבללם ויטול מן התערובת מעשר \u0003ונמצא תורם מן החדש שבו על החדש שבו,\u0004 ו\u0003מן הישן שבו על הישן שבו!\u0004","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 כיוצא בזו, ש\u0003ר' יוסי בן כיפר אמר משום ר' שמעון שזורי: פול המצרי שזרעו לזרע,\u0004 כלומר, לא לאכילתו כירק אלא לצורך אכילת וזריעת זרעיו, \u0003מקצתו\u0004 של הפול \u0003השריש לפני ראש השנה, ומקצתו השריש לאחר ראש השנה\u0004 — \u0003אין תורמין ומעשרין מזה על זה, לפי שאין תורמין ומעשרין לא מן החדש על הישן ולא מן הישן על החדש.\u0004","\u0003כיצד הוא עושה\u0004 בהפרשת המעשרות שלא יבוא לטעות ולהפריש שלא כראוי — \u0003צובר גורנו לתוכו\u0004 שמניח ובולל יחד הכול במקום אחד, ומפריש \u0003ונמצא תורם ומעשר מן החדש שבו על החדש שבו, ומן הישן שבו על הישן שבו.\u0004 ומדוע אין עושים כן אף באורז ודוחן?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003ר' שמעון שזורי קאמרת\u0004 \u0005[אמרת]?\u0006 מדבריו אין להקשות, כי \u0003ר' שמעון שזורי סבר יש בילה,\u0004 שלדעתו, דברים שהונחו בתערובת מחשיבים אנו אותם כאילו נבללו בלילה גמורה, ומה שמוציא מהם — מוציא לפי יחסי התערובת הראשונה.","\u0003ו\u0004אולם \u0003רבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 \u0003אין בילה\u0004 בכיוצא בזה, לכן אין התקנה של צבירת הכל יחד מועילה לדעת חכמים.","\u0003אמר ר' יצחק בר נחמני אמר שמואל: הלכה כר' יוסי בן כיפר שאמר משום ר' שמעון שזורי. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: לכל אין בילה,\u0004 שדברים המעורבים אינם נחשבים כבלולים לגמרי \u0003חוץ מיין\u0004 חדש שעירב עם הישן \u0003ושמן\u0004 חדש שעירב עם הישן וכן שאר נוזלים, ואם כן כיצד פסק כר' שמעון שזורי?","ומעירים בתשובה לכך: \u0003אשתמיטתיה\u0004 \u0005[נשמט ממנו,\u0006 שכח\u0005]\u0006 ר' זירא \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר שמואל: הכל\u0004 במעשרות \u0003הולך אחר גמר פרי\u0004 וזמן זה הוא הקובע את שנת המעשר. ולפי שיטה זו זמן ההשרשה אינו מעלה ואינו מוריד, ולכן יכול שמואל לפסוק כר' שמעון שזורי אבל לא מטעם בילה — טעמו של ר' שמעון שזורי עצמו — כי אם משום שלדעתו כל היבול מבשיל כאחת ושייך לשנה אחת ומתעשר כאחד."]]};
